window.CHAPTERS=window.CHAPTERS||{};window.CHAPTERS["ch06"]={"id":"ch06","title":"第六章 真核生物的转录及其调控（一）","sub":"朱玉贤《现代分子生物学》第5版 · 教师PPT第6章-1","sub2":"真核RNA聚合酶 · 启动子分类 · II类启动子 · 调控元件","modules":[{"i":0,"name":"模块一：真核生物RNA聚合酶","slides":[{"i":0,"page":1,"sec":"模块一：真核生物RNA聚合酶","title":"Chapter 6","notes":"本页主题：Chapter 6\nPPT内容：Chapter 6；真核生物的转录及其调控\n本页详解：本页是第六章（一）的封面。第六章的主题是“真核生物的转录及其调控”；本章先讲真核RNA聚合酶，再讲启动子和增强子/沉默子/绝缘子。学习时先建立“不同RNA聚合酶识别不同启动子”的总框架。","points":["Chapter 6","真核生物的转录及其调控"],"level":"理解","img":"assets/img/ch06/p001.jpg","src":"教师PPT","check":{"id":"ch06_ck_0_0","kind":"mcq","q":"第六章（一）的主线是真核生物的（ ）","a":"B","e":"正确答案：转录及调控。真核转录及调控是本章主线。","src":"PPT对应自测","modI":0,"o":["A. 逆转录","B. 转录及调控","C. DNA复制","D. 翻译"]}},{"i":1,"page":2,"sec":"模块一：真核生物RNA聚合酶","title":"1 真核生物RNA聚合酶 （Multiple forms of eukaryotic RNA polymerase）","notes":"本页主题：1 真核生物RNA聚合酶 （Multiple forms of eukaryotic RNA polymerase）\nPPT内容：：1 真核生物RNA聚合酶 （Multiple forms of eukaryotic RNA polymerase）；2 启动子（Promoters）；1） II类启动子-被RNA聚合酶II识别（Class II promoters – recognized by RNA polymerase II）；2） I类启动子-被RNA聚合酶I识别（Class I promoters – recognized by RNA polymerase I）；3） III类启动子-被RNA聚合酶III识别（Class III promoters – recognized by RNA polymerase III）；3 增强子和绝缘子（Enhancers and Insulators）；1）增强子（Enhancers）、超级增强子（super-enhancer）；2）沉默子（Silencers）；3）绝缘子（Insulators）；Chapter 6-1；真核生物RNA聚合酶和它们的启动子；（Eukaryotic RNA Polymerases and Their Promoters）\n讲解：本章分三部分学习：①真核生物RNA聚合酶（Pol I/II/III及植物Pol IV/V）；②真核启动子（I/II/III类）；③增强子、沉默子、绝缘子等调控元件。先建立“不同聚合酶负责不同RNA、识别不同启动子”的框架。\n英文术语：RNA聚合酶；超级增强子；聚合酶；启动子；增强子；RNA（核糖核酸）\n本页详解：本页是本章目录。英文标题“Eukaryotic RNA Polymerases and Their Promoters”意思是“真核RNA聚合酶及其启动子”。本章分三块：①真核RNA聚合酶（Pol I/II/III及植物Pol IV/V）；②三类启动子；③增强子、沉默子和绝缘子。先记住“Pol I→rRNA，Pol II→mRNA前体，Pol III→tRNA/5S rRNA等”的分工。","points":["1 真核生物RNA聚合酶 （Multiple forms of eukaryotic RNA polymerase）","2 启动子（Promoters）","1） II类启动子-被RNA聚合酶II识别（Class II promoters – recognized by RNA polymerase II）","2） I类启动子-被RNA聚合酶I识别（Class I promoters – recognized by RNA polymerase I）","3） III类启动子-被RNA聚合酶III识别（Class III promoters – recognized by RNA polymerase III）","3 增强子和绝缘子（Enhancers and Insulators）","英文术语：RNA聚合酶；超级增强子；聚合酶；启动子；增强子；RNA（核糖核酸）"],"level":"理解","img":"assets/img/ch06/p002.jpg","src":"教师PPT","check":{"id":"ch06_ck_0_1","kind":"mcq","q":"真核生物主要的三类RNA聚合酶是（ ）","a":"C","e":"正确答案：Pol I、Pol II和Pol III。真核细胞主要有Pol I、Pol II、Pol III三类RNA聚合酶。","src":"PPT对应自测","modI":0,"o":["A. RNAP I、RNAP II和RNAP IV","B. Pol I、Pol III和Pol IV","C. Pol I、Pol II和Pol III","D. Pol α、Pol β和Pol γ"]}},{"i":2,"page":3,"sec":"模块一：真核生物RNA聚合酶","title":"1 Eukaryotic RNA polymerase","notes":"本页主题：1 Eukaryotic RNA polymerase\nPPT内容：1 Eukaryotic RNA polymerase\n讲解：真核RNA聚合酶不是单一酶，而是多亚基蛋白复合物：Pol I位于核仁，转录rRNA前体；Pol II位于核质，转录mRNA前体及部分snRNA；Pol III位于核质，转录tRNA、5S rRNA、U6 snRNA等。真核RNA聚合酶不能独立识别启动子，必须依靠通用转录因子和基因特异转录因子；植物还有Pol IV/V。\n英文术语：RNA聚合酶；聚合酶；RNA（核糖核酸）\n本页详解：“Eukaryotic RNA polymerase”即真核RNA聚合酶。真核细胞不是只有一种RNA聚合酶，而是有Pol I、Pol II、Pol III等多种多亚基复合物：Pol I主要在核仁转录rRNA前体，Pol II在核质转录mRNA前体及部分snRNA，Pol III在核质转录tRNA、5S rRNA和部分小RNA。真核RNA聚合酶不能单独识别启动子，必须依赖转录因子。","points":["1 Eukaryotic RNA polymerase","英文术语：RNA聚合酶；聚合酶；RNA（核糖核酸）"],"level":"理解","img":"assets/img/ch06/p003.jpg","src":"教师PPT","check":{"id":"ch06_ck_0_2","kind":"mcq","q":"用α-鹅膏蕈碱区分真核RNA聚合酶，依据的是它们对毒素的（ ）不同","a":"D","e":"正确答案：敏感性。三类RNA聚合酶对α-鹅膏蕈碱的敏感性不同。","src":"PPT对应自测","modI":0,"o":["A. 分子量","B. 电荷","C. 最适温度","D. 敏感性"]}},{"i":3,"page":4,"sec":"模块一：真核生物RNA聚合酶","title":"1、真核生物的转录发生在细胞核；原核生物的转录发生在拟核；","notes":"本页主题：1、真核生物的转录发生在细胞核；原核生物的转录发生在拟核；\nPPT内容：：1、真核生物的转录发生在细胞核；原核生物的转录发生在拟核；；2、真核生物为单顺反子；原核生物为多顺反子；；3、真核生物有多种不同的RNA聚合酶催化合成RNA；原核生物只有一种RNA聚合酶催化合成所有的RNA;；4、真核生物的RNA聚合酶转录需要转录因子的协助，其对启动子的识别比原核生物复杂的多；原核生物的RNA聚合酶可直接起始转录。；真核生物的转录过程比原核生物更加复杂\n讲解：真核与原核转录的关键差异：真核转录在细胞核，原核在拟核；真核mRNA多为单顺反子，原核常为多顺反子；真核有多种RNA聚合酶，原核通常只有一种；真核需要转录因子协助，原核RNA聚合酶可直接起始；真核转录还受染色质和核小体影响。\n英文术语：RNA（核糖核酸）\n本页详解：本页比较真核与原核转录。要点：①真核转录在细胞核，原核在拟核；②真核mRNA多为单顺反子，原核常为多顺反子；③真核有多种RNA聚合酶，原核通常只有一种；④真核需要转录因子帮助识别启动子，原核RNA聚合酶可直接起始；⑤真核还要面对染色质/核小体。考试常把这几条做成比较题。","points":["1、真核生物的转录发生在细胞核；原核生物的转录发生在拟核；","2、真核生物为单顺反子；原核生物为多顺反子；","3、真核生物有多种不同的RNA聚合酶催化合成RNA；原核生物只有一种RNA聚合酶催化合成所有的RNA;","4、真核生物的RNA聚合酶转录需要转录因子的协助，其对启动子的识别比原核生物复杂的多；原核生物的RNA聚合酶可直接起始转录。","真核生物的转录过程比原核生物更加复杂","英文术语：RNA（核糖核酸）"],"level":"掌握","img":"assets/img/ch06/p004.jpg","src":"教师PPT","check":{"id":"ch06_ck_0_3","kind":"mcq","q":"真核mRNA通常为（ ），原核生物常为多顺反子","a":"A","e":"正确答案：单顺反子。真核mRNA一般一个mRNA编码一条多肽链，为单顺反子。","src":"PPT对应自测","modI":0,"o":["A. 单顺反子","B. 多顺反子","C. 环状","D. 双链"]}},{"i":4,"page":5,"sec":"模块一：真核生物RNA聚合酶","title":"Sea urchin embryos","notes":"本页主题：Sea urchin embryos\nPPT内容：：Sea urchin embryos；DEAE-Sephadex ion- exchange chromatography；Green, protein content；Red, RNA polymerase activity；RNA polymerase I；RNA polymerase II；RNA polymerase III；New insight:；RNA polymerase IV；RNA polymerase V；1.1 Multiple forms of eukaryotic RNA polymerase\n讲解：本页用海胆胚胎提取物和DEAE-Sephadex离子交换层析分离RNA聚合酶活性，得到Pol I、Pol II、Pol III等不同峰，证明真核细胞中存在多种RNA聚合酶。学习时抓住“离子交换层析分离—不同活性峰—多种聚合酶”这一实验逻辑。\n英文术语：RNA聚合酶；聚合酶；RNA（核糖核酸）\n本页详解：英文标题“Multiple forms of eukaryotic RNA polymerase”是“真核RNA聚合酶的多种形式”。实验用海胆胚胎提取物做DEAE-Sephadex离子交换层析：绿色曲线是蛋白质含量，红色曲线是RNA聚合酶活性；活性出现多个峰，分别对应Pol I、Pol II、Pol III，说明真核细胞存在多种RNA聚合酶。读图时抓住“离子交换层析分离→不同活性峰→多种聚合酶”。","points":["Sea urchin embryos","DEAE-Sephadex ion- exchange chromatography","Green, protein content","Red, RNA polymerase activity","RNA polymerase I","RNA polymerase II","英文术语：RNA聚合酶；聚合酶；RNA（核糖核酸）"],"level":"掌握","img":"assets/img/ch06/p005.jpg","src":"教师PPT","check":{"id":"ch06_ck_0_4","kind":"mcq","q":"分离真核RNA聚合酶时，利用电荷差异常用（ ）","a":"B","e":"正确答案：离子交换层析。离子交换层析按电荷差异分离蛋白质。","src":"PPT对应自测","modI":0,"o":["A. 超速离心","B. 离子交换层析","C. 亲和层析","D. 凝胶过滤"]}},{"i":5,"page":6,"sec":"模块一：真核生物RNA聚合酶","title":"根据对α-鹅膏蕈碱(α-amanitin)的敏感性不同，分为3类。","notes":"本页主题：根据对α-鹅膏蕈碱(α-amanitin)的敏感性不同，分为3类。\nPPT内容：：根据对α-鹅膏蕈碱(α-amanitin)的敏感性不同，分为3类。\n讲解：α-鹅膏蕈碱敏感性是区分三类RNA聚合酶的经典依据：Pol I不敏感，Pol II最敏感（低浓度即抑制），Pol III敏感性居中。做实验或选择题时先看“对α-鹅膏蕈碱是否敏感”，再对应聚合酶类型。\n英文术语：α-鹅膏蕈碱\n本页详解：本页讲α-鹅膏蕈碱（α-amanitin）敏感性。三种真核RNA聚合酶对它的敏感程度不同：Pol I不敏感，Pol II最敏感（低浓度即被抑制），Pol III居中。做实验题或选择题时，先看“对α-鹅膏蕈碱是否敏感”，再判断是哪一类RNA聚合酶。","points":["根据对α-鹅膏蕈碱(α-amanitin)的敏感性不同，分为3类。","英文术语：α-鹅膏蕈碱"],"level":"掌握","img":"assets/img/ch06/p006.jpg","src":"教师PPT","check":{"id":"ch06_ck_0_5","kind":"mcq","q":"对α-鹅膏蕈碱最敏感的RNA聚合酶是（ ）","a":"C","e":"正确答案：RNA聚合酶II。Pol II对α-鹅膏蕈碱最敏感。","src":"PPT对应自测","modI":0,"o":["A. RNA聚合酶III","B. RNA聚合酶IV","C. RNA聚合酶II","D. RNA聚合酶I"]}},{"i":6,"page":7,"sec":"模块一：真核生物RNA聚合酶","title":"真核 rDNA 的基因片段包含 18S、5.8S 和 28S ，并形成串联重复簇","notes":"本页主题：真核 rDNA 的基因片段包含 18S、5.8S 和 28S ，并形成串联重复簇\nPPT内容：真核 rDNA 的基因片段包含 18S、5.8S 和 28S ，并形成串联重复簇；The gene segment of eukaryotic rDNA contains 18S, 5.8S, and 28S tracts and forms a tandem repetitive cluster.；the 5S rDNA is coded separately.；NTS, nontranscribed spacer,；ETS, external transcribed spacer,；ITS, internal transcribed spacers 1 and 2, numbered from 5' end.；RNA polymerase I:；Relative activity:50%-70%；Location: Nucleoli 核仁；Product:28S/18S/5.8S rRNA；TSS；TSS\n讲解：rDNA编码45S/47S rRNA前体，加工为18S、5.8S、28S rRNA；5S rRNA由Pol III转录。\n英文术语：RNA聚合酶；聚合酶；rRNA（核糖体RNA）；rDNA（核糖体DNA）；RNA（核糖核酸）\n本页详解：本页讲真核rDNA。英文“The gene segment of eukaryotic rDNA contains 18S, 5.8S, and 28S tracts and forms a tandem repetitive cluster”意思是：真核rDNA含18S、5.8S、28S序列，并呈串联重复簇。45S/47S rRNA前体经加工形成18S、5.8S、28S rRNA；5S rDNA由Pol III单独转录。NTS、ETS、ITS分别是非转录间隔区、外部转录间隔区、内部转录间隔区。","points":["真核 rDNA 的基因片段包含 18S、5.8S 和 28S ，并形成串联重复簇","the 5S rDNA is coded separately.","NTS, nontranscribed spacer,","ETS, external transcribed spacer,","ITS, internal transcribed spacers 1 and 2, numbered from 5' end.","RNA polymerase I:","英文术语：RNA聚合酶；聚合酶；rRNA（核糖体RNA）；rDNA（核糖体DNA）；RNA（核糖核酸）"],"level":"理解","img":"assets/img/ch06/p007.jpg","src":"教师PPT","check":{"id":"ch06_ck_0_6","kind":"fill","q":"真核rDNA编码的rRNA前体可加工成18S、5.8S和______rRNA。","a":"28S","e":"答案：28S。真核rDNA单元主要产生18S、5.8S和28S rRNA。","src":"PPT对应自测","modI":0}},{"i":7,"page":8,"sec":"模块一：真核生物RNA聚合酶","title":"人类基因组中有数百个rDNA，线性排列在5条染色体上。（Human genomes encode hundreds ","notes":"本页主题：人类基因组中有数百个rDNA，线性排列在5条染色体上。（Human genomes encode hundreds \nPPT内容：人类基因组中有数百个rDNA，线性排列在5条染色体上。（Human genomes encode hundreds of copies of the rDNA operon, which are arranged in tandem arrays on five chromosomes (13, 14, 15, 21, and 22).；每个 rDNA 类操纵子编码一个 47S pre-rRNA，该 rRNA 在转录后加工成小核糖体亚基的 18S rRNA 和大核糖体亚基的 5.8S 和 28S rRNA。(Each rDNA operon encodes a 47S pre-rRNA that is posttranscriptionally processed into the 18S rRNA of the small ribosomal subunit and the 5.8S and 28S rRNAs of the large ribosomal subunit.)；人类亦有数十至数百个5S rRNA拷贝，位于1号染色体。（Human also have tens to hundreds of copies of 5S rRNA, a third rRNA component of the large subunit on chromosomes 1）.；人类基因组中的rDNA\n英文术语：rRNA前体；亚基；操纵子；rRNA（核糖体RNA）；rDNA（核糖体DNA）\n本页详解：本页讲人类rDNA的基因组组织。英文“Human genomes encode hundreds of copies of the rDNA operon...”意思是人类基因组有数百个rDNA操纵子拷贝，串联排列在13、14、15、21、22号染色体上；每个单元编码47S pre-rRNA，再加工成18S、5.8S、28S rRNA。5S rRNA拷贝位于1号染色体，由Pol III转录。","points":["人类基因组中的rDNA","英文术语：rRNA前体；亚基；操纵子；rRNA（核糖体RNA）；rDNA（核糖体DNA）"],"level":"理解","img":"assets/img/ch06/p008.jpg","src":"教师PPT","check":{"id":"ch06_ck_0_7","kind":"mcq","q":"人类rDNA单元串联重复，每个单元编码（ ）前体","a":"A","e":"正确答案：rRNA。rDNA是核糖体RNA基因，转录产生rRNA前体。","src":"PPT对应自测","modI":0,"o":["A. rRNA","B. mRNA","C. tRNA","D. snRNA"]}},{"i":8,"page":9,"sec":"模块一：真核生物RNA聚合酶","title":"Fig. the human rDNA unit is operon-like.","notes":"本页主题：Fig. the human rDNA unit is operon-like.\nPPT内容：Fig. the human rDNA unit is operon-like.；Matthew M. Parks et al. Sci Adv 2018;4:eaao0665\n英文术语：操纵子；rDNA（核糖体DNA）\n本页详解：“Fig. the human rDNA unit is operon-like”意思是人类rDNA单元在结构上类似操纵子：多个rRNA基因和间隔区成串排列、协同转录。注意这里的“operon-like”是结构相似，不是说rDNA受细菌操纵子那样的阻遏蛋白调控。","points":["Fig. the human rDNA unit is operon-like.","Matthew M. Parks et al. Sci Adv 2018;4:eaao0665","英文术语：操纵子；rDNA（核糖体DNA）"],"level":"理解","img":"assets/img/ch06/p009.jpg","src":"教师PPT","check":{"id":"ch06_ck_0_8","kind":"mcq","q":"人类rDNA单元的结构与（ ）类似","a":"B","e":"正确答案：操纵子。rDNA单元成串排列，结构上与操纵子类似。","src":"PPT对应自测","modI":0,"o":["A. 复制子","B. 操纵子","C. 增强子","D. 启动子"]}},{"i":9,"page":10,"sec":"模块一：真核生物RNA聚合酶","title":"RNA polymerase II:","notes":"本页主题：RNA polymerase II:\nPPT内容：RNA polymerase II:；hnRNAs: heterogeneous nuclear RNAs(不均一的核RNAs), the most are precursors of mRNAs；snRNAs: small nuclear RNAs (小的核RNAs), participate in the maturation of hnRNAs to mRNAs，在RNA转录后加工中起重要作用，是真核生物转录后核内mRNA加工过程中RNA剪接体spilceosome的主要成分；Relative activity:20%-40%；Location: Nucleoplasm 核质；Product: hnRNA、snRNA\n英文术语：RNA聚合酶；聚合酶；snRNA（小核RNA）；hnRNA（不均一核RNA）；mRNA（信使RNA）；RNA（核糖核酸）\n本页详解：本页讲RNA聚合酶II。英文“hnRNAs: heterogeneous nuclear RNAs, the most are precursors of mRNAs”意思是hnRNA是不均一核RNA，多数是mRNA前体；“snRNAs: small nuclear RNAs”是小核RNA，参与hnRNA加工和剪接体组成。Pol II位于核质，相对活性约20%–40%，产物主要是hnRNA和snRNA。","points":["RNA polymerase II:","hnRNAs: heterogeneous nuclear RNAs(不均一的核RNAs), the most are precursors of mRNAs","Relative activity:20%-40%","Location: Nucleoplasm 核质","Product: hnRNA、snRNA","英文术语：RNA聚合酶；聚合酶；snRNA（小核RNA）；hnRNA（不均一核RNA）；mRNA（信使RNA）；RNA（核糖核酸）"],"level":"掌握","img":"assets/img/ch06/p010.jpg","src":"教师PPT","check":{"id":"ch06_ck_0_9","kind":"mcq","q":"RNA聚合酶II主要转录（ ）","a":"C","e":"正确答案：hnRNA/mRNA前体。Pol II位于核质，主要转录mRNA前体。","src":"PPT对应自测","modI":0,"o":["A. 5S rRNA","B. rRNA前体","C. hnRNA/mRNA前体","D. tRNA"]}},{"i":10,"page":11,"sec":"模块一：真核生物RNA聚合酶","title":"RNA polymerase III:","notes":"本页主题：RNA polymerase III:\nPPT内容：RNA polymerase III:；tRNAs: Transfer RNA,将密码子对应的氨基酸转运至核糖体合成中的多肽链上；snRNAs: small nuclear RNAs (小的核RNAs), participate in the maturation of hnRNAs to mRNAs，在RNA转录后加工中起重要作用，是真核生物转录后核内mRNA加工过程中RNA剪接体spilceosome的主要成分；Relative activity:~10%；Location: Nucleoplasm 核质；Product: 5srRNA、tRNA、snRNA\n英文术语：RNA聚合酶；聚合酶；snRNA（小核RNA）；mRNA（信使RNA）；tRNA（转运RNA）；RNA（核糖核酸）\n本页详解：本页讲RNA聚合酶III。英文“tRNAs: Transfer RNA”是转运RNA，把氨基酸运到核糖体；“snRNAs”是小核RNA。Pol III位于核质，相对活性约10%，主要产物是5S rRNA、tRNA和部分snRNA。记忆时把Pol III和“小RNA、tRNA、5S rRNA”绑定。","points":["RNA polymerase III:","tRNAs: Transfer RNA,将密码子对应的氨基酸转运至核糖体合成中的多肽链上","Relative activity:~10%","Location: Nucleoplasm 核质","Product: 5srRNA、tRNA、snRNA","英文术语：RNA聚合酶；聚合酶；snRNA（小核RNA）；mRNA（信使RNA）；tRNA（转运RNA）；RNA（核糖核酸）"],"level":"掌握","img":"assets/img/ch06/p011.jpg","src":"教师PPT","check":{"id":"ch06_ck_0_10","kind":"mcq","q":"RNA聚合酶III主要转录（ ）","a":"D","e":"正确答案：tRNA、5S rRNA和部分snRNA。Pol III主要转录tRNA、5S rRNA和部分小RNA。","src":"PPT对应自测","modI":0,"o":["A. mRNA前体","B. rRNA前体","C. 线粒体RNA","D. tRNA、5S rRNA和部分snRNA"]}},{"i":11,"page":12,"sec":"模块一：真核生物RNA聚合酶","title":"RNA polymerase III：Relative activity:~10%","notes":"本页主题：RNA polymerase III：Relative activity:~10%\nPPT内容：RNA polymerase III：Relative activity:~10%；Location: Nucleoplasm 核质；5S rRNA；tRNA；U6 and U2 snRNA: small RNAs that participate in RNA splicing (RNA剪接)；7SL RNA: a small RNA involved in signal peptide recognition (SPR) 信号肽识别 in the synthesis of secreted proteins；7SK RNA: a small nuclear RNA that binds and inhibits the class II transcription elongation factor P-TEFb；The common SINE family Alu probably originated from a 7SL RNA gene after deletion of a central sequence\n英文术语：RNA聚合酶；转录；识别；聚合酶；延伸；snRNA（小核RNA）；rRNA（核糖体RNA）；tRNA（转运RNA）；RNA（核糖核酸）\n本页详解：本页继续列Pol III产物。英文“U6 and U2 snRNA: small RNAs that participate in RNA splicing”意思是U6/U2 snRNA参与RNA剪接；“7SL RNA”参与分泌蛋白合成中的信号肽识别；“7SK RNA”可抑制P-TEFb，调节Pol II延伸。注意U6主要由Pol III转录，而U2通常由Pol II转录，题干常在这里设易错点。","points":["RNA polymerase III：Relative activity:~10%","Location: Nucleoplasm 核质","5S rRNA","U6 and U2 snRNA: small RNAs that participate in RNA splicing (RNA剪接)","英文术语：RNA聚合酶；转录；识别；聚合酶；延伸；snRNA（小核RNA）；rRNA（核糖体RNA）；tRNA（转运RNA）；RNA（核糖核酸）"],"level":"掌握","img":"assets/img/ch06/p012.jpg","src":"教师PPT","check":{"id":"ch06_ck_0_11","kind":"mcq","q":"RNA聚合酶III在细胞中的相对活性约为（ ）。","a":"A","e":"正确答案：10%。Pol III的相对活性约为10%。","src":"PPT对应自测","modI":0,"o":["A. 10%","B. 5%","C. 50%","D. 90%"]}},{"i":12,"page":13,"sec":"模块一：真核生物RNA聚合酶","title":"模块一：真核生物RNA聚合酶 · 第13页","notes":"本页主题：模块一：真核生物RNA聚合酶 · 第13页\nPPT内容：47S\n讲解：本模块讲真核RNA聚合酶：Pol I/II/III的产物、位置、α-鹅膏蕈碱敏感性，以及亚基、CTD和蛋白复合物研究方法。\n英文术语：RNA（核糖核酸）\n本页详解：本页是模块一过渡页，核心是把Pol I/II/III的产物、位置、α-鹅膏蕈碱敏感性和亚基结构串起来。看到“47S”要联想到rRNA前体加工。","points":["模块一：真核生物RNA聚合酶的图示关系","结合图片复述本页核心概念","英文术语：RNA（核糖核酸）"],"level":"理解","img":"assets/img/ch06/p013.jpg","src":"教师PPT","check":{"id":"ch06_ck_0_12","kind":"fill","q":"模块一的主题是真核生物RNA______。","a":"聚合酶","e":"答案：聚合酶。模块一介绍真核生物RNA聚合酶的类型和结构。","src":"PPT对应自测","modI":0}},{"i":13,"page":14,"sec":"模块一：真核生物RNA聚合酶","title":"RNA polymerase IV 植物中特异的RNA聚合酶，产生小RNA","notes":"本页主题：RNA polymerase IV 植物中特异的RNA聚合酶，产生小RNA\nPPT内容：RNA polymerase IV 植物中特异的RNA聚合酶，产生小RNA；Pol IV: siRNA (silences certain transposons and repetitive DNA)；2005 Herr et al., in Science；除了所有真核生物共有的三种 RNA 聚合酶（RNAP I-III）外，植物基因组还编码第四种 RNAP（RNAP IV），它似乎专门用于产生 siRNA。；In addition to the three RNA polymerases (RNAP I–III) shared by all eukaryotic organisms, plant genomes encode a fourth RNAP (RNAP IV) that appears to be specialized in the production of siRNAs. (Zhang et al., 2007 in PNAS)\n英文术语：RNA聚合酶；聚合酶；Pol IV（RNA聚合酶IV）；siRNA（小干扰RNA）；RNAP（RNA聚合酶）；RNA（核糖核酸）；DNA（脱氧核糖核酸）\n本页详解：本页讲植物特有的RNA聚合酶IV。英文“RNA polymerase IV ... appears to be specialized in the production of siRNAs”意思是Pol IV似乎专门产生siRNA；siRNA可沉默某些转座子和重复DNA。Pol IV不是所有真核生物都有，植物中较特殊。","points":["RNA polymerase IV 植物中特异的RNA聚合酶，产生小RNA","Pol IV: siRNA (silences certain transposons and repetitive DNA)","2005 Herr et al., in Science","除了所有真核生物共有的三种 RNA 聚合酶（RNAP I-III）外，植物基因组还编码第四种 RNAP（RNAP IV），它似乎专门用于产生 siRNA。","英文术语：RNA聚合酶；聚合酶；Pol IV（RNA聚合酶IV）；siRNA（小干扰RNA）；RNAP（RNA聚合酶）；RNA（核糖核酸）；DNA（脱氧核糖核酸）"],"level":"理解","img":"assets/img/ch06/p014.jpg","src":"教师PPT","check":{"id":"ch06_ck_0_13","kind":"mcq","q":"植物RNA聚合酶IV主要产生（ ）","a":"C","e":"正确答案：siRNA。Pol IV参与产生小干扰RNA，参与转座子沉默。","src":"PPT对应自测","modI":0,"o":["A. tRNA","B. rRNA","C. siRNA","D. mRNA"]}},{"i":14,"page":15,"sec":"模块一：真核生物RNA聚合酶","title":"RNA 聚合酶 V 是一种存在于细胞核中的多亚基植物特异性 RNA 聚合酶。 （RNA polymerase V i","notes":"本页主题：RNA 聚合酶 V 是一种存在于细胞核中的多亚基植物特异性 RNA 聚合酶。 （RNA polymerase V i\nPPT内容：RNA 聚合酶 V 是一种存在于细胞核中的多亚基植物特异性 RNA 聚合酶。 （RNA polymerase V is a multisubunit plant specific RNA polymerase found in nucleus. Together with RNA polymerase IV required for normal function and biogenesis of small interferring RNA (siRNA)）.；Pol V 涉及siRNA指导的DNA甲基化，会导致异染色质沉默。（Pol V is involved in siRNA-directed DNA methylation pathway which leads to heterochromatic silencing.）；RNA polymerase V is composed of 12 subunits that are paralogous to RNA polymerase II subunits. Two largest subunits (catalytic site) is the most conserved region sharing similarity with eukaryotic and bacterial polymerases.；RNA polymerase V ——植物中特异的RNA聚合酶，产生小RNA。有12个亚基。；2008 Wierzbicki et al., in Cell\n英文术语：RNA聚合酶；聚合酶；Pol V（RNA聚合酶V）；siRNA（小干扰RNA）；RNA（核糖核酸）；DNA（脱氧核糖核酸）\n本页详解：本页讲植物RNA聚合酶V。英文“RNA polymerase V is a multisubunit plant specific RNA polymerase found in nucleus”意思是Pol V是细胞核内的多亚基植物特异RNA聚合酶；它与Pol IV共同参与siRNA的正常功能和生成。Pol V参与siRNA指导的DNA甲基化，导致异染色质沉默；它约有12个亚基，催化中心与Pol II亚基同源。","points":["RNA polymerase V ——植物中特异的RNA聚合酶，产生小RNA。有12个亚基。","2008 Wierzbicki et al., in Cell","英文术语：RNA聚合酶；聚合酶；Pol V（RNA聚合酶V）；siRNA（小干扰RNA）；RNA（核糖核酸）；DNA（脱氧核糖核酸）"],"level":"理解","img":"assets/img/ch06/p015.jpg","src":"教师PPT","check":{"id":"ch06_ck_0_14","kind":"mcq","q":"植物RNA聚合酶V参与RNA介导的DNA（ ）","a":"D","e":"正确答案：甲基化。Pol V参与RNA介导的DNA甲基化。","src":"PPT对应自测","modI":0,"o":["A. 复制","B. 转录","C. 修复","D. 甲基化"]}},{"i":15,"page":16,"sec":"模块一：真核生物RNA聚合酶","title":"1.2 RNA polymerase subunit structures（亚基结构）","notes":"本页主题：1.2 RNA polymerase subunit structures（亚基结构）\nPPT内容：1.2 RNA polymerase subunit structures（亚基结构）；1、巨大：超过500KDa；2、多亚基组成：8-16亚基组成。；均含有两个大亚基RBP1和RBP2（>100KDa），与细菌RNA聚合酶的β´和β亚基同源；共有小亚基（三种聚合酶共同具有的亚基），功能不是很清楚：Rbp5,6,8,10,12\n英文术语：RNA聚合酶；聚合酶；亚基；RNA（核糖核酸）\n本页详解：“RNA polymerase subunit structures”即RNA聚合酶亚基结构。真核RNA聚合酶相对分子质量很大（常超过500 kDa），由8–16个亚基组成；都有两个大亚基RPB1、RPB2，分别与细菌RNA聚合酶的β′、β亚基同源；还有RPB5、6、8、10、12等共享小亚基。","points":["1.2 RNA polymerase subunit structures（亚基结构）","1、巨大：超过500KDa","2、多亚基组成：8-16亚基组成。","均含有两个大亚基RBP1和RBP2（>100KDa），与细菌RNA聚合酶的β´和β亚基同源","共有小亚基（三种聚合酶共同具有的亚基），功能不是很清楚：Rbp5,6,8,10,12","英文术语：RNA聚合酶；聚合酶；亚基；RNA（核糖核酸）"],"level":"掌握","img":"assets/img/ch06/p016.jpg","src":"教师PPT","check":{"id":"ch06_ck_0_15","kind":"mcq","q":"真核RNA聚合酶最大亚基RPB1与细菌RNA聚合酶的（ ）同源","a":"A","e":"正确答案：β′。RPB1与细菌RNA聚合酶β′亚基同源。","src":"PPT对应自测","modI":0,"o":["A. β′","B. β","C. α","D. σ"]}},{"i":16,"page":17,"sec":"模块一：真核生物RNA聚合酶","title":"聚合酶中都有两个相对分子较大的大亚基和若干小亚基；","notes":"本页主题：聚合酶中都有两个相对分子较大的大亚基和若干小亚基；\nPPT内容：聚合酶中都有两个相对分子较大的大亚基和若干小亚基；；最大亚基与 E. coli RNA聚合酶中的β´亚基相似；第二亚基与E. coli 的含有活性位点的β亚基相似；同种生物3类聚合酶有“共享”小亚基的倾向，至少有5种小亚基普遍存在于3种酶中。\n英文术语：大肠杆菌；RNA（核糖核酸）\n本页详解：本页强调所有真核RNA聚合酶都含两个大亚基和若干小亚基：最大亚基类似E. coli的β′，第二亚基类似含活性位点的β；三类聚合酶还倾向共享至少5种小亚基。大亚基负责催化，小亚基参与组装和调控。","points":["聚合酶中都有两个相对分子较大的大亚基和若干小亚基；","最大亚基与 E. coli RNA聚合酶中的β´亚基相似","第二亚基与E. coli 的含有活性位点的β亚基相似","同种生物3类聚合酶有“共享”小亚基的倾向，至少有5种小亚基普遍存在于3种酶中。","英文术语：大肠杆菌；RNA（核糖核酸）"],"level":"掌握","img":"assets/img/ch06/p017.jpg","src":"教师PPT","check":{"id":"ch06_ck_0_16","kind":"mcq","q":"三类真核RNA聚合酶共享的小亚基包括RPB5、6、8、10和（ ）。","a":"B","e":"正确答案：RPB12。RPB12是三类真核RNA聚合酶共享的小亚基。","src":"PPT对应自测","modI":0,"o":["A. RPB4","B. RPB12","C. RPB1","D. RPB2"]}},{"i":17,"page":18,"sec":"模块一：真核生物RNA聚合酶","title":"RNA polymerase II/B: 12 subunits, each of these polypeptid","notes":"本页主题：RNA polymerase II/B: 12 subunits, each of these polypeptid\nPPT内容：RNA polymerase II/B: 12 subunits, each of these polypeptides is encoded in a single gene in the yeast and human genomes.；蛋白质(RPB):大写正体; 基因(RPB):大写斜体； 突变体(rpb): 小写斜体\n英文术语：RNA聚合酶；聚合酶；RNA（核糖核酸）；RPB（RNA聚合酶亚基）\n本页详解：本页讲Pol II的12个亚基。英文“RNA polymerase II/B: 12 subunits, each of these polypeptides is encoded in a single gene in the yeast and human genomes”意思是Pol II有12个亚基，每个多肽由单独基因编码。命名规范：蛋白质RPB大写正体，基因RPB大写斜体，突变体rpb小写斜体。","points":["蛋白质(RPB):大写正体; 基因(RPB):大写斜体； 突变体(rpb): 小写斜体","英文术语：RNA聚合酶；聚合酶；RNA（核糖核酸）；RPB（RNA聚合酶亚基）"],"level":"掌握","img":"assets/img/ch06/p018.jpg","src":"教师PPT","check":{"id":"ch06_ck_0_17","kind":"mcq","q":"酵母RNA聚合酶II约由（ ）个亚基组成。","a":"C","e":"正确答案：12。酵母Pol II约由12个亚基组成。","src":"PPT对应自测","modI":0,"o":["A. 10","B. 14","C. 12","D. 8"]}},{"i":18,"page":19,"sec":"模块一：真核生物RNA聚合酶","title":"Yeast RNA polymerase II","notes":"本页主题：Yeast RNA polymerase II\nPPT内容：核心亚基；Yeast RNA polymerase II\n讲解：本模块讲真核RNA聚合酶：Pol I/II/III的产物、位置、α-鹅膏蕈碱敏感性，以及亚基、CTD和蛋白复合物研究方法。\n英文术语：RNA聚合酶；聚合酶；RNA（核糖核酸）\n本页详解：“Yeast RNA polymerase II”即酵母Pol II，是研究真核转录的经典模型。酵母Pol II的亚基组成和结构与人Pol II高度相似，很多亚基功能可以通过酵母遗传学实验推断。","points":["Yeast RNA polymerase II","英文术语：RNA聚合酶；聚合酶；RNA（核糖核酸）"],"level":"理解","img":"assets/img/ch06/p019.jpg","src":"教师PPT","check":{"id":"ch06_ck_0_18","kind":"fill","q":"酵母Pol II是研究真核RNA聚合酶结构与功能的常用______。","a":"模型","e":"答案：模型。酵母Pol II是研究真核转录机制的经典模型。","src":"PPT对应自测","modI":0}},{"i":19,"page":20,"sec":"模块一：真核生物RNA聚合酶","title":"The three-dimensional structure of RNA polymerase II","notes":"本页主题：The three-dimensional structure of RNA polymerase II\nPPT内容：The three-dimensional structure of RNA polymerase II；Crystal structure of yeast RNA polymerase II, lacking Rpb4 and Rbp7 (pol II Δ4/7) (Science 2002), see page 280\n英文术语：RNA聚合酶；聚合酶；Pol II（RNA聚合酶II）；RNA（核糖核酸）；RPB（RNA聚合酶亚基）\n本页详解：本页是酵母Pol II的三维结构图。英文“Crystal structure of yeast RNA polymerase II, lacking Rpb4 and Rbp7”意思是缺少Rpb4/Rpb7的酵母Pol II晶体结构；这种Δ4/7形式仍能解析核心结构。读图时注意聚合酶像“钳子”一样夹住DNA。","points":["The three-dimensional structure of RNA polymerase II","英文术语：RNA聚合酶；聚合酶；Pol II（RNA聚合酶II）；RNA（核糖核酸）；RPB（RNA聚合酶亚基）"],"level":"掌握","img":"assets/img/ch06/p020.jpg","src":"教师PPT","check":{"id":"ch06_ck_0_19","kind":"fill","q":"RNA聚合酶II三维结构具有一个深的DNA结合______。","a":"沟","e":"答案：沟。Pol II的DNA结合沟容纳模板DNA。","src":"PPT对应自测","modI":0}},{"i":20,"page":21,"sec":"模块一：真核生物RNA聚合酶","title":"Features:","notes":"本页主题：Features:\nPPT内容：Features:；A deep DNA-binding cleft that can accept a linear DNA template. 一个深的DNA结合沟；Containing two Mg2+ ions, one at the base of the cleft. 沟的底部有一个Mg2+；A highly mobile clamp 高度灵活的夹子；Core enzyme of RNA polymerase in Thermus aquaticus；原核 Vs 真核\n英文术语：RNA聚合酶；核心酶；聚合酶；模板；结合；RNA（核糖核酸）；DNA（脱氧核糖核酸）\n本页详解：本页列Pol II结构特征。英文“A deep DNA-binding cleft that can accept a linear DNA template”意思是有一条深的DNA结合沟，可容纳线状DNA模板；“Containing two Mg2+ ions, one at the base of the cleft”是沟底含两个Mg2+，其中一个是催化离子；“A highly mobile clamp”是可高度移动的夹子，帮助酶夹紧DNA。","points":["Features:","A deep DNA-binding cleft that can accept a linear DNA template. 一个深的DNA结合沟","Containing two Mg2+ ions, one at the base of the cleft. 沟的底部有一个Mg2+","A highly mobile clamp 高度灵活的夹子","Core enzyme of RNA polymerase in Thermus aquaticus","原核 Vs 真核","英文术语：RNA聚合酶；核心酶；聚合酶；模板；结合；RNA（核糖核酸）；DNA（脱氧核糖核酸）"],"level":"理解","img":"assets/img/ch06/p021.jpg","src":"教师PPT","check":{"id":"ch06_ck_0_20","kind":"mcq","q":"Pol II DNA结合沟底部含有（ ）离子。","a":"B","e":"正确答案：Mg2+。Pol II活性中心含Mg2+，催化RNA合成。","src":"PPT对应自测","modI":0,"o":["A. Ca2+","B. Mg2+","C. Mn2+","D. Zn2+"]}},{"i":21,"page":22,"sec":"模块一：真核生物RNA聚合酶","title":"当敲除酵母RNA聚合酶II的亚基后，大多数致死的！！","notes":"本页主题：当敲除酵母RNA聚合酶II的亚基后，大多数致死的！！\nPPT内容：当敲除酵母RNA聚合酶II的亚基后，大多数致死的！！\n讲解：本模块讲真核RNA聚合酶：Pol I/II/III的产物、位置、α-鹅膏蕈碱敏感性，以及亚基、CTD和蛋白复合物研究方法。\n英文术语：RNA（核糖核酸）\n本页详解：本页讲酵母Pol II亚基敲除实验：大多数亚基敲除后致死，说明它们对酶活性和细胞生存必不可少。少数非必需亚基可能在特定条件下才发挥作用。","points":["当敲除酵母RNA聚合酶II的亚基后，大多数致死的！！","英文术语：RNA（核糖核酸）"],"level":"理解","img":"assets/img/ch06/p022.jpg","src":"教师PPT","check":{"id":"ch06_ck_0_21","kind":"judge","q":"敲除酵母RNA聚合酶II的CTD重复序列约50%通常会致死。","a":"对","e":"CTD重复序列对Pol II功能重要，大幅缺失可致死。","src":"PPT对应自测","modI":0}},{"i":22,"page":23,"sec":"模块一：真核生物RNA聚合酶","title":"7 Aa的重复单位：Tyr-Ser-Pro-Thr-Ser-Pro-Ser","notes":"本页主题：7 Aa的重复单位：Tyr-Ser-Pro-Thr-Ser-Pro-Ser\nPPT内容：7 Aa的重复单位：Tyr-Ser-Pro-Thr-Ser-Pro-Ser；缺失50%重复序列时致死；Tyr-SerP-Pro-ThrP-SerP-Pro-SerP；CTD(柔性C端结构域) of RNA polymerase II\n英文术语：RNA聚合酶；聚合酶；RNA（核糖核酸）；CTD（C端结构域）\n本页详解：本页讲Pol II的CTD（C端结构域）。英文“7 Aa的重复单位：Tyr-Ser-Pro-Thr-Ser-Pro-Ser”是七肽重复序列；丝氨酸可被磷酸化；缺失约50%重复序列会致死。CTD像柔性尾巴，负责招募加工因子，把转录和RNA加工连接起来。","points":["7 Aa的重复单位：Tyr-Ser-Pro-Thr-Ser-Pro-Ser","缺失50%重复序列时致死","Tyr-SerP-Pro-ThrP-SerP-Pro-SerP","CTD(柔性C端结构域) of RNA polymerase II","英文术语：RNA聚合酶；聚合酶；RNA（核糖核酸）；CTD（C端结构域）"],"level":"掌握","img":"assets/img/ch06/p023.jpg","src":"教师PPT","check":{"id":"ch06_ck_0_22","kind":"mcq","q":"RNA聚合酶II CTD七肽重复序列的第七个氨基酸是（ ）","a":"D","e":"正确答案：Ser。CTD七肽重复为Tyr-Ser-Pro-Thr-Ser-Pro-Ser，第七位是Ser。","src":"PPT对应自测","modI":0,"o":["A. Thr","B. Tyr","C. Pro","D. Ser"]}},{"i":23,"page":24,"sec":"模块一：真核生物RNA聚合酶","title":"如何解析RNA聚合酶II的亚基组成？","notes":"本页主题：如何解析RNA聚合酶II的亚基组成？\nPPT内容：如何解析RNA聚合酶II的亚基组成？；关键问题：；细胞中蛋白质众多，如何分离目的蛋白质复合物？\n讲解：解析Pol II亚基组成可用co-IP：非变性裂解细胞，用抗体沉淀目标亚基，鉴定共沉淀蛋白；也可用表位标签纯化复合物并结合质谱。\n英文术语：RNA（核糖核酸）\n本页详解：本页提出“如何解析Pol II亚基组成”。核心思路是：细胞中蛋白很多，必须先分离Pol II复合物，再鉴定其组分；可用免疫共沉淀（co-IP）或表位标签纯化，再结合质谱。","points":["如何解析RNA聚合酶II的亚基组成？","细胞中蛋白质众多，如何分离目的蛋白质复合物？","英文术语：RNA（核糖核酸）"],"level":"理解","img":"assets/img/ch06/p024.jpg","src":"教师PPT","qa":[{"q":"如何解析RNA聚合酶II的亚基组成？","a":"可用免疫共沉淀（co-IP）：非变性裂解细胞，用抗目标亚基抗体沉淀，鉴定共沉淀蛋白；也可将表位标签融合到目标亚基，用标签抗体纯化复合物，再结合质谱鉴定亚基组成。"}],"check":{"id":"ch06_ck_0_23","kind":"mcq","q":"解析Pol II亚基组成常用（ ）","a":"A","e":"正确答案：co-IP和表位标签纯化。co-IP和表位标签可用于分离并鉴定Pol II复合物。","src":"PPT对应自测","modI":0,"o":["A. co-IP和表位标签纯化","B. PCR和测序","C. 电泳和透析","D. 离心和盐析"]}},{"i":24,"page":25,"sec":"模块一：真核生物RNA聚合酶","title":"免疫共沉淀（Co-immunoprecipitation, co-IP）","notes":"本页主题：免疫共沉淀（Co-immunoprecipitation, co-IP）\nPPT内容：免疫共沉淀（Co-immunoprecipitation, co-IP）；当细胞在非变性条件下被裂解时，完整细胞内存在的许多蛋白质—蛋白质间的相互作用被保留了下来。如果用蛋白质X的抗体免疫沉淀X，那么与X在体内结合的蛋白质Y也能沉淀下来。这种方法常用于测定两种目标蛋白质是否在体内结合，也可用于确定一种特定蛋白质的新的结合蛋白。\n讲解：co-IP原理：非变性条件下保留蛋白互作，用蛋白X抗体沉淀X，与X结合的Y也被共沉淀；用于鉴定蛋白复合物和相互作用。\n英文术语：co-IP（免疫共沉淀）\n本页详解：“Co-immunoprecipitation, co-IP”是免疫共沉淀。英文原理：非变性裂解细胞时，蛋白质相互作用被保留；用蛋白X的抗体沉淀X，与X结合的蛋白Y也会被一起沉淀。它用于判断两种蛋白是否在体内结合，也可寻找新的结合伙伴。","points":["免疫共沉淀（Co-immunoprecipitation, co-IP）","英文术语：co-IP（免疫共沉淀）"],"level":"理解","img":"assets/img/ch06/p025.jpg","src":"教师PPT","check":{"id":"ch06_ck_0_24","kind":"judge","q":"co-IP中，与目标蛋白结合的蛋白质也会被共沉淀。","a":"对","e":"免疫共沉淀利用抗体沉淀目标蛋白，同时带下其结合蛋白。","src":"PPT对应自测","modI":0}},{"i":25,"page":26,"sec":"模块一：真核生物RNA聚合酶","title":"模块一：真核生物RNA聚合酶 · 第26页","notes":"本页主题：模块一：真核生物RNA聚合酶 · 第26页\nPPT内容：本页为图示/过渡页。\n讲解：本模块讲真核RNA聚合酶：Pol I/II/III的产物、位置、α-鹅膏蕈碱敏感性，以及亚基、CTD和蛋白复合物研究方法。\n英文术语：RNA（核糖核酸）\n本页详解：本页是模块一过渡页，重点是把“RNA聚合酶类型—亚基—CTD—蛋白复合物研究方法”连起来。","points":["模块一：真核生物RNA聚合酶的图示关系","结合图片复述本页核心概念","英文术语：RNA（核糖核酸）"],"level":"理解","img":"assets/img/ch06/p026.jpg","src":"教师PPT","check":{"id":"ch06_ck_0_25","kind":"mcq","q":"图示免疫沉淀的基本流程是：细胞裂解→加抗体→结合→洗涤→（ ）","a":"C","e":"正确答案：洗脱。免疫沉淀最后用洗脱缓冲液把目标蛋白复合物洗脱下来。","src":"PPT对应自测","modI":0,"o":["A. 转膜","B. 测序","C. 洗脱","D. 电泳"]}},{"i":26,"page":27,"sec":"模块一：真核生物RNA聚合酶","title":"Epitope tagging技术解析RNA聚合酶II的亚基组成","notes":"本页主题：Epitope tagging技术解析RNA聚合酶II的亚基组成\nPPT内容：Epitope tagging技术解析RNA聚合酶II的亚基组成\n讲解：本模块讲真核RNA聚合酶：Pol I/II/III的产物、位置、α-鹅膏蕈碱敏感性，以及亚基、CTD和蛋白复合物研究方法。\n英文术语：表位标签；RNA（核糖核酸）\n本页详解：“Epitope tagging”是表位标签技术：把短标签融合到目标蛋白上，用抗标签抗体检测、纯化目标蛋白及其复合物。与co-IP相比，它更适合没有现成抗体的蛋白；两者都可结合质谱鉴定亚基。","points":["Epitope tagging技术解析RNA聚合酶II的亚基组成","英文术语：表位标签；RNA（核糖核酸）"],"level":"理解","img":"assets/img/ch06/p027.jpg","src":"教师PPT","check":{"id":"ch06_ck_0_26","kind":"mcq","q":"表位标签技术主要用于（ ）","a":"D","e":"正确答案：检测和纯化目标蛋白。表位标签便于检测、纯化和鉴定目标蛋白复合物。","src":"PPT对应自测","modI":0,"o":["A. 直接改变DNA序列","B. 抑制转录","C. 切割RNA","D. 检测和纯化目标蛋白"]}}]},{"i":1,"name":"模块二：启动子总论与I类启动子","slides":[{"i":0,"page":28,"sec":"模块二：启动子总论与I类启动子","title":"2 Eukaryotic promoters真核生物的启动子","notes":"本页主题：2 Eukaryotic promoters真核生物的启动子\nPPT内容：2 Eukaryotic promoters真核生物的启动子；1、真核生物的RNA聚合酶不能独立起始转录，而需要转录因子的协助。；2、真核生物的启动子是转录起始所必需的序列元件，即包括转录起始复合物中所有转录因子结合位点的区域。\n英文术语：启动子；RNA（核糖核酸）\n本页详解：“Eukaryotic promoters”是真核启动子。真核RNA聚合酶不能独立起始转录，需要转录因子；启动子是转录起始必需的DNA序列，包含转录起始复合物中所有转录因子结合位点的区域。","points":["2 Eukaryotic promoters真核生物的启动子","1、真核生物的RNA聚合酶不能独立起始转录，而需要转录因子的协助。","2、真核生物的启动子是转录起始所必需的序列元件，即包括转录起始复合物中所有转录因子结合位点的区域。","英文术语：启动子；RNA（核糖核酸）"],"level":"掌握","img":"assets/img/ch06/p028.jpg","src":"教师PPT","check":{"id":"ch06_ck_1_0","kind":"mcq","q":"真核启动子是转录起始所必需的（ ）","a":"A","e":"正确答案：DNA序列。启动子是DNA上的序列元件。","src":"PPT对应自测","modI":1,"o":["A. DNA序列","B. 蛋白质","C. RNA","D. 小分子效应物"]}},{"i":1,"page":29,"sec":"模块二：启动子总论与I类启动子","title":"2.1 真核生物的启动子分类","notes":"本页主题：2.1 真核生物的启动子分类\nPPT内容：2.1 真核生物的启动子分类；包括三类:；1、类别I启动子（Class I promoter）:；由RNA聚合酶I介导转录；2、类别II启动子（Class II promoter）：；由RNA聚合酶II介导转录；3、类别III启动子（Class III promoter）：；由RNA聚合酶III介导转录\n讲解：真核启动子分I、II、III类，分别由Pol I、II、III识别；II类最复杂。\n英文术语：启动子；RNA（核糖核酸）\n本页详解：真核启动子分三类：I类由Pol I识别，II类由Pol II识别，III类由Pol III识别。II类启动子最复杂，也最常考；看到“TATA框、Inr、BRE、DPE”要归到II类。","points":["2.1 真核生物的启动子分类","1、类别I启动子（Class I promoter）:","由RNA聚合酶I介导转录","2、类别II启动子（Class II promoter）：","由RNA聚合酶II介导转录","3、类别III启动子（Class III promoter）：","英文术语：启动子；RNA（核糖核酸）"],"level":"理解","img":"assets/img/ch06/p029.jpg","src":"教师PPT","check":{"id":"ch06_ck_1_1","kind":"mcq","q":"I、II、III类启动子分别由（ ）识别","a":"B","e":"正确答案：Pol I、Pol II和Pol III。三类启动子分别由对应的RNA聚合酶识别。","src":"PPT对应自测","modI":1,"o":["A. Pol I、Pol III和Pol II","B. Pol I、Pol II和Pol III","C. Pol II、Pol I和Pol III","D. Pol III、Pol II和Pol I"]}},{"i":2,"page":30,"sec":"模块二：启动子总论与I类启动子","title":"由转录起始位点附近的两部分序列构成：","notes":"本页主题：由转录起始位点附近的两部分序列构成：\nPPT内容：由转录起始位点附近的两部分序列构成：；核心启动子（core promoter）：位于-45到+20；负责转录的起始，单独存在时就足以起始转录。；上游控制元件（upstream control element，UCE/ upstream promoter element UPE）：；位于-170至-107，与核心启动子的转录起始效率有关；RNA pol I只负责转录rRNA，只有一种启动子类型；；2.1.1 RNA聚合酶I的启动子(I类启动子)\n英文术语：启动子；Pol I（RNA聚合酶I）；rRNA（核糖体RNA）；RNA（核糖核酸）；UPE（上游启动子元件）；UCE（上游控制元件）\n本页详解：本页讲I类启动子（Pol I）。它由核心启动子（core promoter，约-45至+20）和上游控制元件（UPE/UCE，约-170至-107）组成；核心元件足以起始基础转录，UPE提高转录效率。","points":["由转录起始位点附近的两部分序列构成：","核心启动子（core promoter）：位于-45到+20","负责转录的起始，单独存在时就足以起始转录。","上游控制元件（upstream control element，UCE/ upstream promoter element UPE）：","位于-170至-107，与核心启动子的转录起始效率有关","RNA pol I只负责转录rRNA，只有一种启动子类型；","英文术语：启动子；Pol I（RNA聚合酶I）；rRNA（核糖体RNA）；RNA（核糖核酸）；UPE（上游启动子元件）；UCE（上游控制元件）"],"level":"掌握","img":"assets/img/ch06/p030.jpg","src":"教师PPT","check":{"id":"ch06_ck_1_2","kind":"fill","q":"I类启动子由核心启动子和______组成。","a":"UPE","e":"答案：UPE。I类启动子由核心启动子和上游启动子元件UPE组成。","src":"PPT对应自测","modI":1}},{"i":3,"page":31,"sec":"模块二：启动子总论与I类启动子","title":"启动子有两个重要区域：UPE（-156至-107）和核心（-45至+20）。这两个元件之间的间距很重要（The pr","notes":"本页主题：启动子有两个重要区域：UPE（-156至-107）和核心（-45至+20）。这两个元件之间的间距很重要（The pr\nPPT内容：启动子有两个重要区域：UPE（-156至-107）和核心（-45至+20）。这两个元件之间的间距很重要（The promoter has two important regions: UPE (-156 to -107) and Core (-45 to +20). The spacing between these two elements is important.）；UPE是最佳转录所必需的，但在缺乏UPE的情况下，基础转录是可能的。核心元素是任何转录发生所必需的。（The UPE is necessary for optimal transcription, but basal transcription is possible in its absence. The core element is absolutely required for any transcription to occur.）；Cell, 1986；Human rRNA gene promoter elements. 人类rRNA基因的启动子元件\n讲解：I类启动子由核心启动子（约-45至+20）和UPE（约-170至-107）组成，两者间距重要；核心负责起始，UPE提高效率。\n英文术语：转录；启动子；rRNA（核糖体RNA）；UPE（上游启动子元件）\n本页详解：英文“The promoter has two important regions: UPE (-156 to -107) and Core (-45 to +20). The spacing between these two elements is important.”意思是I类启动子有UPE和核心两个区域，二者间距重要。UPE缺失时仍可有基础转录，但核心元件是任何转录都必需的。","points":["Cell, 1986","Human rRNA gene promoter elements. 人类rRNA基因的启动子元件","英文术语：转录；启动子；rRNA（核糖体RNA）；UPE（上游启动子元件）"],"level":"理解","img":"assets/img/ch06/p031.jpg","src":"教师PPT","check":{"id":"ch06_ck_1_3","kind":"judge","q":"I类启动子的UPE和核心元件之间的间距很重要。","a":"对","e":"UPE与核心元件的间距会影响启动子功能。","src":"PPT对应自测","modI":1}},{"i":4,"page":32,"sec":"模块二：启动子总论与I类启动子","title":"I类启动子的序列在不同物种之间并不完全一致（The class I promoters are not well c","notes":"本页主题：I类启动子的序列在不同物种之间并不完全一致（The class I promoters are not well c\nPPT内容：I类启动子的序列在不同物种之间并不完全一致（The class I promoters are not well conserved in sequence from one species to another）。；在各物种之间，I类启动子的序列保守性较低。\n英文术语：启动子\n本页详解：英文“The class I promoters are not well conserved in sequence from one species to another”意思是I类启动子序列在不同物种间保守性较低。不同物种的Pol I启动子可差异较大，但核心和UPE的功能逻辑相似。","points":["在各物种之间，I类启动子的序列保守性较低。","英文术语：启动子"],"level":"理解","img":"assets/img/ch06/p032.jpg","src":"教师PPT","check":{"id":"ch06_ck_1_4","kind":"judge","q":"I类启动子的序列在不同物种之间高度保守。","a":"错","e":"I类启动子序列在不同物种间保守性较低。","src":"PPT对应自测","modI":1}}]},{"i":2,"name":"模块三：II类启动子与调控元件","slides":[{"i":0,"page":33,"sec":"模块三：II类启动子与调控元件","title":"2.1.1 RNA聚合酶II的启动子(II类启动子)","notes":"本页主题：2.1.1 RNA聚合酶II的启动子(II类启动子)\nPPT内容：2.1.1 RNA聚合酶II的启动子(II类启动子)；最复杂；(对鹅膏蕈碱最敏感)\n讲解：II类启动子由核心启动子和上游调控元件组成；核心含TATA、Inr、BRE、DPE等。\n英文术语：RNA（核糖核酸）\n本页详解：本页讲II类启动子（Pol II）。它最复杂，对α-鹅膏蕈碱最敏感；由核心启动子和上游调控元件组成。核心启动子决定转录起始，上游元件提高效率和特异性。","points":["2.1.1 RNA聚合酶II的启动子(II类启动子)","最复杂；(对鹅膏蕈碱最敏感)","英文术语：RNA（核糖核酸）"],"level":"理解","img":"assets/img/ch06/p033.jpg","src":"教师PPT","check":{"id":"ch06_ck_2_0","kind":"mcq","q":"II类启动子对α-鹅膏蕈碱（ ）","a":"B","e":"正确答案：最敏感。Pol II启动子对α-鹅膏蕈碱最敏感。","src":"PPT对应自测","modI":2,"o":["A. 只在高温敏感","B. 最敏感","C. 最不敏感","D. 完全不敏感"]}},{"i":1,"page":34,"sec":"模块三：II类启动子与调控元件","title":"Core promoter: contains up to six elements","notes":"本页主题：Core promoter: contains up to six elements\nPPT内容：Core promoter: contains up to six elements；TATA box: centered about 25 bp upstream of the transcription start site；BRE : TFIIB recognition element；Inr (Initiator): the transcription start site；DCE: Downstream core element (three parts)；MTE: motif ten element；DPE: downstream promoter element；不同的基因，所含有的顺式作用元件不同！；具体基因，具体对待！\n讲解：II类核心启动子最多含六种元件：TATA、BRE、Inr、DPE等；TATA约-25 bp，Inr在起始位点。\n英文术语：转录；识别；启动子；TATA框；TFIIB（转录因子IIB）；Inr（起始子）；BRE（TFIIB识别元件）；DPE（下游启动子元件）；bp（碱基对）\n本页详解：“Core promoter: contains up to six elements”意思是II类核心启动子最多含六类元件：TATA框、BRE（TFIIB识别元件）、Inr（起始子）、DCE（下游核心元件）、MTE（十基序元件）、DPE（下游启动子元件）。TATA框常位于转录起始位点上游约-25 bp，Inr覆盖起始位点；不同基因使用的元件组合不同。","points":["Core promoter: contains up to six elements","TATA box: centered about 25 bp upstream of the transcription start site","BRE : TFIIB recognition element","Inr (Initiator): the transcription start site","DCE: Downstream core element (three parts)","MTE: motif ten element","英文术语：转录；识别；启动子；TATA框；TFIIB（转录因子IIB）；Inr（起始子）；BRE（TFIIB识别元件）；DPE（下游启动子元件）；bp（碱基对）"],"level":"掌握","img":"assets/img/ch06/p034.jpg","src":"教师PPT","check":{"id":"ch06_ck_2_1","kind":"mcq","q":"II类核心启动子可含TATA、BRE、Inr和（ ）等元件。","a":"C","e":"正确答案：DPE。II类核心启动子可含TATA、BRE、Inr和DPE。","src":"PPT对应自测","modI":2,"o":["A. MTE","B. OCE","C. DPE","D. CPE"]}},{"i":2,"page":35,"sec":"模块三：II类启动子与调控元件","title":"①core promoter-起始子(initiator，Inr)","notes":"本页主题：①core promoter-起始子(initiator，Inr)\nPPT内容：①core promoter-起始子(initiator，Inr)；对于启动子的强度和起始位点的选择都是十分重要。；转录起始位点：帽子位点（Cap site），与原核的转录起始位点相似 ，多为A；；PyPyAN(T/A)PyPy构成（Py：嘧啶；Pu：嘌呤）；；可能提供RNA pol II识别；；结构特点：；功能：\n英文术语：启动子；Pol II（RNA聚合酶II）；RNA（核糖核酸）；CAP（代谢物激活蛋白）；Inr（起始子）\n本页详解：本页讲起始子Inr。Inr位于转录起始位点附近，影响启动子强度和起始位点选择；其一致序列大致为PyPyAN(T/A)PyPy（Py=嘧啶，Pu=嘌呤），常以A为起始位点。它可帮助Pol II识别启动子。","points":["①core promoter-起始子(initiator，Inr)","对于启动子的强度和起始位点的选择都是十分重要。","转录起始位点：帽子位点（Cap site），与原核的转录起始位点相似 ，多为A；","PyPyAN(T/A)PyPy构成（Py：嘧啶；Pu：嘌呤）；","可能提供RNA pol II识别；","英文术语：启动子；Pol II（RNA聚合酶II）；RNA（核糖核酸）；CAP（代谢物激活蛋白）；Inr（起始子）"],"level":"掌握","img":"assets/img/ch06/p035.jpg","src":"教师PPT","check":{"id":"ch06_ck_2_2","kind":"mcq","q":"Inr主要影响（ ）","a":"D","e":"正确答案：起始位点选择和启动子强度。Inr位于起始位点附近，影响起始位点选择和启动子强度。","src":"PPT对应自测","modI":2,"o":["A. 转录终止","B. RNA剪接","C. polyA加尾","D. 起始位点选择和启动子强度"]}},{"i":3,"page":36,"sec":"模块三：II类启动子与调控元件","title":"② core promoter- TATA Box（Hogness Box)","notes":"本页主题：② core promoter- TATA Box（Hogness Box)\nPPT内容：② core promoter- TATA Box（Hogness Box)；结构特点：；in general, at -25 bp position；一致序列为T82A97T93A85A63(T37)A83A50(T37)；功能：；1、与RNA聚合酶的定位有关（失去TATA框，转录将在许多位点上开始）；即确定转录起始位点，与转录效率无关；2、双链解开区域；3、绝大多数真核基因的正确表达所必需的；in housekeeping genes and in developmentally regulated genes, no TATA box\n英文术语：启动子；TATA框；RNA（核糖核酸）；bp（碱基对）\n本页详解：本页讲TATA框（Hogness box）。TATA框通常位于转录起始位点上游约-25 bp，一致序列富含T和A；功能包括定位RNA聚合酶、确定起始位点、帮助双链解开。失去TATA框后转录可能在多个位点起始；一些管家基因和发育调控基因可以没有TATA框。","points":["② core promoter- TATA Box（Hogness Box)","in general, at -25 bp position","一致序列为T82A97T93A85A63(T37)A83A50(T37)","1、与RNA聚合酶的定位有关（失去TATA框，转录将在许多位点上开始）；即确定转录起始位点，与转录效率无关","2、双链解开区域","3、绝大多数真核基因的正确表达所必需的","英文术语：启动子；TATA框；RNA（核糖核酸）；bp（碱基对）"],"level":"掌握","img":"assets/img/ch06/p036.jpg","src":"教师PPT","check":{"id":"ch06_ck_2_3","kind":"mcq","q":"TATA框通常位于转录起始位点上游约（ ）bp。","a":"A","e":"正确答案：-25。TATA框常位于起始位点上游约-25 bp。","src":"PPT对应自测","modI":2,"o":["A. -25","B. -10","C. -35","D. -75"]}},{"i":4,"page":37,"sec":"模块三：II类启动子与调控元件","title":"II类启动子","notes":"本页主题：II类启动子\nPPT内容：II类启动子；核心启动子；core promoter；近端调控元件:；upstream promoter elements；上游元件\n英文术语：启动子\n本页详解：本页区分II类启动子的核心启动子和上游启动子元件。核心启动子负责基础转录；上游元件（近端启动子元件）常结合基因特异转录因子，提高转录效率和细胞类型特异性。","points":["II类启动子","core promoter","近端调控元件:","upstream promoter elements","英文术语：启动子"],"level":"理解","img":"assets/img/ch06/p037.jpg","src":"教师PPT","check":{"id":"ch06_ck_2_4","kind":"mcq","q":"II类启动子由核心启动子和（ ）组成","a":"B","e":"正确答案：上游启动子元件。II类启动子包括核心启动子和上游启动子元件。","src":"PPT对应自测","modI":2,"o":["A. 绝缘子","B. 上游启动子元件","C. 增强子","D. 沉默子"]}},{"i":5,"page":38,"sec":"模块三：II类启动子与调控元件","title":"常表现细胞类型的转录特异性，其功能主要是提高转录效率和转录特异性。","notes":"本页主题：常表现细胞类型的转录特异性，其功能主要是提高转录效率和转录特异性。\nPPT内容：常表现细胞类型的转录特异性，其功能主要是提高转录效率和转录特异性。\n讲解：本模块讲II类启动子：TATA、Inr、BRE、DPE，以及GC/CAAT框、增强子、沉默子、绝缘子。\n本页详解：本页讲近端启动子元件的功能：常表现细胞类型的转录特异性，主要提高转录效率和转录特异性。它们与核心启动子不同，通常结合基因特异性转录因子。","points":["常表现细胞类型的转录特异性，其功能主要是提高转录效率和转录特异性。"],"level":"理解","img":"assets/img/ch06/p038.jpg","src":"教师PPT","check":{"id":"ch06_ck_2_5","kind":"mcq","q":"近端启动子元件常表现细胞类型的转录（ ）","a":"C","e":"正确答案：特异性。近端启动子元件常决定细胞类型特异的转录。","src":"PPT对应自测","modI":2,"o":["A. 组成性","B. 无关系","C. 特异性","D. 通用性"]}},{"i":6,"page":39,"sec":"模块三：II类启动子与调控元件","title":"GC框: 位于上游, 结合转录因子Sp1","notes":"本页主题：GC框: 位于上游, 结合转录因子Sp1\nPPT内容：GC框: 位于上游, 结合转录因子Sp1；疱疹病毒的tk基因的启动子含有两个GC框：GGGCGG 和 CCGCCC，分别位于-47~-61位, -80~-105位；SV40早期基因启动子含有6个GC框.\n讲解：GC框核心序列GGGCGG，常结合Sp1，无方向性，位于上游提高转录效率。\n英文术语：Sp1（GC框结合因子）；GC框\n本页详解：本页讲GC框。GC框位于上游，核心序列GGGCGG，常结合转录因子Sp1；它没有方向性，反转后仍可起作用。疱疹病毒tk启动子含两个GC框，SV40早期启动子含多个GC框。","points":["GC框: 位于上游, 结合转录因子Sp1","疱疹病毒的tk基因的启动子含有两个GC框：GGGCGG 和 CCGCCC，分别位于-47~-61位, -80~-105位","SV40早期基因启动子含有6个GC框.","英文术语：Sp1（GC框结合因子）；GC框"],"level":"掌握","img":"assets/img/ch06/p039.jpg","src":"教师PPT","check":{"id":"ch06_ck_2_6","kind":"fill","q":"GC框的核心序列是______。","a":"GGGCGG","e":"答案：GGGCGG。GC框富含GC，核心序列为GGGCGG。","src":"PPT对应自测","modI":2}},{"i":7,"page":40,"sec":"模块三：II类启动子与调控元件","title":"CAAT Box","notes":"本页主题：CAAT Box\nPPT内容：CAAT Box；典型核心序列为 CCAAT，经典共识序列为 GG(C/T)CAATCT。；通常通过结合特异性转录因子调节转录起始效率。；核心序列及其侧翼碱基共同影响转录因子的结合能力。；GC Box；核心序列为GGGCGG；；GC框没有方向性，即反转180度，仍然起作用；a. 近侧启动子元件（Proximal Promoter Elements）；与核心启动子不同的是：近侧启动子元件通常与相应的基因特异性转录因子结合:如GC盒与Sp1结合；CCAAT盒与CTF结合。\n讲解：CAAT框核心序列CCAAT，经典序列GG(C/T)CAATCT，结合特异转录因子调节起始效率。\n英文术语：启动子；CAAT框；GC框；Sp1（GC框结合因子）\n本页详解：本页讲CAAT框和GC框。CAAT框典型核心序列CCAAT，经典共识序列GG(C/T)CAATCT，结合CTF等转录因子，调节转录起始效率；GC框核心序列GGGCGG，结合Sp1。二者都属于近端启动子元件，与核心启动子不同。","points":["CAAT Box","典型核心序列为 CCAAT，经典共识序列为 GG(C/T)CAATCT。","通常通过结合特异性转录因子调节转录起始效率。","核心序列及其侧翼碱基共同影响转录因子的结合能力。","GC Box","核心序列为GGGCGG；","英文术语：启动子；CAAT框；GC框；Sp1（GC框结合因子）"],"level":"掌握","img":"assets/img/ch06/p040.jpg","src":"教师PPT","check":{"id":"ch06_ck_2_7","kind":"fill","q":"CAAT框的典型核心序列是______。","a":"CCAAT","e":"答案：CCAAT。CAAT框的核心序列为CCAAT。","src":"PPT对应自测","modI":2}},{"i":8,"page":41,"sec":"模块三：II类启动子与调控元件","title":"GC框增强基因转录，其突变导致转录产物的减少。","notes":"本页主题：GC框增强基因转录，其突变导致转录产物的减少。\nPPT内容：GC框增强基因转录，其突变导致转录产物的减少。\n讲解：本模块讲II类启动子：TATA、Inr、BRE、DPE，以及GC/CAAT框、增强子、沉默子、绝缘子。\n英文术语：GC框\n本页详解：本页强调GC框增强基因转录：GC框突变后转录产物减少。说明GC框是正调控元件，不是可有可无的序列。","points":["GC框增强基因转录，其突变导致转录产物的减少。","英文术语：GC框"],"level":"理解","img":"assets/img/ch06/p041.jpg","src":"教师PPT","check":{"id":"ch06_ck_2_8","kind":"judge","q":"GC框突变通常会导致转录产物减少。","a":"对","e":"GC框增强转录，突变后转录产物减少。","src":"PPT对应自测","modI":2}},{"i":9,"page":42,"sec":"模块三：II类启动子与调控元件","title":"b. 增强子 （Enhancers)","notes":"本页主题：b. 增强子 （Enhancers)\nPPT内容：b. 增强子 （Enhancers)；1、增强子为顺式反应元件，通过和转录因子的结合增强基因转录。；2、无方向性；3、可位于启动子的上游或下游。；Function/Behavior of the 72-bp repeats:；delete the 72-bp repeats: transcription was depressed.；invert or move the 72-bp repeats over 2 kb away from the promoter: transcription was still stimulated.\n讲解：增强子无方向性、位置不依赖，可位于上游或下游，远距离增强转录。\n英文术语：转录；增强子；启动子；bp（碱基对）\n本页详解：本页讲增强子（Enhancers）。增强子是顺式作用元件，通过结合转录因子增强转录；无方向性，可位于启动子上游或下游。英文“delete the 72-bp repeats: transcription was depressed”说明删除72 bp重复序列会降低转录；“invert or move ... over 2 kb ... still stimulated”说明反转或移动到2 kb外仍能增强。","points":["b. 增强子 （Enhancers)","1、增强子为顺式反应元件，通过和转录因子的结合增强基因转录。","2、无方向性","3、可位于启动子的上游或下游。","Function/Behavior of the 72-bp repeats:","delete the 72-bp repeats: transcription was depressed.","英文术语：转录；增强子；启动子；bp（碱基对）"],"level":"掌握","img":"assets/img/ch06/p042.jpg","src":"教师PPT","check":{"id":"ch06_ck_2_9","kind":"mcq","q":"增强子可位于启动子上游或（ ）","a":"C","e":"正确答案：下游。增强子的位置不依赖，可位于上游或下游。","src":"PPT对应自测","modI":2,"o":["A. 仅内含子","B. 仅3′非编码区","C. 下游","D. 仅上游"]}},{"i":10,"page":43,"sec":"模块三：II类启动子与调控元件","title":"增强子是不依赖于位置和方向的DNA元件，可刺激基因转录（Enhancers are position- and or","notes":"本页主题：增强子是不依赖于位置和方向的DNA元件，可刺激基因转录（Enhancers are position- and or\nPPT内容：增强子是不依赖于位置和方向的DNA元件，可刺激基因转录（Enhancers are position- and orientation-independent DNA elements that stimulate the transcription of associated genes）。；Enhancers usually locate upstream of the promoter they control, but sometime we find it within a gene. 如下例所示：\n英文术语：转录；增强子；启动子；DNA（脱氧核糖核酸）\n本页详解：英文“Enhancers are position- and orientation-independent DNA elements that stimulate transcription of associated genes”意思是增强子不依赖位置和方向，能刺激相关基因转录；通常位于启动子上游，但也可在基因内部。关键不是“离得近”，而是通过空间折叠靠近启动子。","points":["模块三：II类启动子与调控元件的图示关系","结合图片复述本页核心概念","英文术语：转录；增强子；启动子；DNA（脱氧核糖核酸）"],"level":"掌握","img":"assets/img/ch06/p043.jpg","src":"教师PPT","check":{"id":"ch06_ck_2_10","kind":"judge","q":"增强子的作用依赖其相对于启动子的位置和方向。","a":"错","e":"增强子作用不依赖位置和方向。","src":"PPT对应自测","modI":2}},{"i":11,"page":44,"sec":"模块三：II类启动子与调控元件","title":"How do enhancers stimulate transcription?","notes":"本页主题：How do enhancers stimulate transcription?\nPPT内容：How do enhancers stimulate transcription?；增强子如何刺激基因转录？；许多基因都有不止一个增强子。这使得细胞能够在不同组织或生物体发育的不同时期对其基因进行精细控制。\n讲解：增强子通过DNA环化与启动子/转录因子接触，招募中介体和RNA聚合酶，促进转录起始。\n英文术语：转录；增强子\n本页详解：“How do enhancers stimulate transcription?”是本页问题。增强子常通过DNA环化，使结合的激活蛋白靠近启动子和RNA聚合酶，招募中介体（Mediator）等共激活因子，促进转录起始。一个基因可以有多个增强子，便于不同组织/发育时期精细调控。","points":["How do enhancers stimulate transcription?","增强子如何刺激基因转录？","许多基因都有不止一个增强子。这使得细胞能够在不同组织或生物体发育的不同时期对其基因进行精细控制。","英文术语：转录；增强子"],"level":"理解","img":"assets/img/ch06/p044.jpg","src":"教师PPT","qa":[{"q":"增强子如何刺激基因转录？","a":"增强子结合转录因子/共激活因子，通过DNA环化与启动子附近的RNA聚合酶II和中介体接触，招募并稳定前启始复合体，从而提高转录起始效率；增强子无方向性、位置不依赖。"}],"check":{"id":"ch06_ck_2_11","kind":"mcq","q":"增强子通过DNA环化招募（ ）促进转录起始","a":"A","e":"正确答案：中介体。增强子与启动子通过DNA环化靠近，招募中介体。","src":"PPT对应自测","modI":2,"o":["A. 中介体","B. 核糖体","C. 剪接体","D. 蛋白酶体"]}},{"i":12,"page":45,"sec":"模块三：II类启动子与调控元件","title":"SE是一类由多个增强子（增强子间间隔小于12.5kb）组成的一簇增强子。","notes":"本页主题：SE是一类由多个增强子（增强子间间隔小于12.5kb）组成的一簇增强子。\nPPT内容：SE是一类由多个增强子（增强子间间隔小于12.5kb）组成的一簇增强子。；超级增强子比普通增强子的调控能力更强，在机体调控过程中起到更重要的作用。；超级增强子（super-enhancer，SE）\n英文术语：超级增强子；增强子\n本页详解：超级增强子（super-enhancer, SE）是一簇增强子，增强子间距通常小于12.5 kb；比普通增强子调控能力更强，常与细胞身份和疾病相关。","points":["SE是一类由多个增强子（增强子间间隔小于12.5kb）组成的一簇增强子。","超级增强子比普通增强子的调控能力更强，在机体调控过程中起到更重要的作用。","超级增强子（super-enhancer，SE）","英文术语：超级增强子；增强子"],"level":"理解","img":"assets/img/ch06/p045.jpg","src":"教师PPT","check":{"id":"ch06_ck_2_12","kind":"mcq","q":"超级增强子比普通增强子的调控能力（ ）","a":"B","e":"正确答案：更强。超级增强子由增强子簇组成，调控能力更强。","src":"PPT对应自测","modI":2,"o":["A. 只抑制","B. 更强","C. 更弱","D. 相同"]}},{"i":13,"page":46,"sec":"模块三：II类启动子与调控元件","title":"沉默子是与位置和方向无关的DNA 元件，可抑制相关基因的转录","notes":"本页主题：沉默子是与位置和方向无关的DNA 元件，可抑制相关基因的转录\nPPT内容：沉默子是与位置和方向无关的DNA 元件，可抑制相关基因的转录；c.抑制子/沉默子（Silencers）；有些DNA元件既可是增强子，也可以是抑制子，这依赖于和其结合的蛋白质。\n英文术语：DNA（脱氧核糖核酸）\n本页详解：沉默子（Silencers）是与位置和方向无关的DNA元件，可抑制相关基因转录。注意：同一DNA元件在不同蛋白结合情况下既可能增强也可能抑制转录。","points":["沉默子是与位置和方向无关的DNA 元件，可抑制相关基因的转录","c.抑制子/沉默子（Silencers）","有些DNA元件既可是增强子，也可以是抑制子，这依赖于和其结合的蛋白质。","英文术语：DNA（脱氧核糖核酸）"],"level":"掌握","img":"assets/img/ch06/p046.jpg","src":"教师PPT","check":{"id":"ch06_ck_2_13","kind":"mcq","q":"沉默子对相关基因转录的作用是（ ）","a":"C","e":"正确答案：抑制。沉默子是抑制转录的DNA元件。","src":"PPT对应自测","modI":2,"o":["A. 无影响","B. 只影响翻译","C. 抑制","D. 激活"]}},{"i":14,"page":47,"sec":"模块三：II类启动子与调控元件","title":"绝缘子是一种 DNA 元件，可保护基因免受增强子的激活或沉默子的抑制（Insulators are DNA elem","notes":"本页主题：绝缘子是一种 DNA 元件，可保护基因免受增强子的激活或沉默子的抑制（Insulators are DNA elem\nPPT内容：绝缘子是一种 DNA 元件，可保护基因免受增强子的激活或沉默子的抑制（Insulators are DNA elements that can shield genes from activation by enhancers or repression by silences）。；Enhancer-blocking activity；增强子阻断活性；Barrier activity；屏障活性；致密的、不活跃的染色质；d.绝缘子（ Insulators ）\n英文术语：增强子；DNA（脱氧核糖核酸）\n本页详解：绝缘子（Insulators）是DNA元件，可保护基因免受邻近增强子的激活或沉默子的抑制；它常通过“增强子阻断活性”和“屏障活性”维持染色质结构域边界。","points":["Enhancer-blocking activity","增强子阻断活性","Barrier activity","致密的、不活跃的染色质","d.绝缘子（ Insulators ）","英文术语：增强子；DNA（脱氧核糖核酸）"],"level":"理解","img":"assets/img/ch06/p047.jpg","src":"教师PPT","check":{"id":"ch06_ck_2_14","kind":"mcq","q":"绝缘子可维持染色质结构域的（ ）","a":"D","e":"正确答案：独立。绝缘子阻断增强子/沉默子对邻近基因的作用，维持结构域独立。","src":"PPT对应自测","modI":2,"o":["A. 融合","B. 复制","C. 降解","D. 独立"]}}]},{"i":3,"name":"模块四：III类启动子","slides":[{"i":0,"page":48,"sec":"模块四：III类启动子","title":"内部启动子/下游启动子:","notes":"本页主题：内部启动子/下游启动子:\nPPT内容：内部启动子/下游启动子:；外部启动子/上游启动子:；2.1.3 RNA聚合酶III的启动子(III类启动子)\n英文术语：RNA（核糖核酸）\n本页详解：本页讲III类启动子的两种位置：内部启动子/下游启动子和外部启动子/上游启动子。III类启动子由Pol III识别，5S rRNA和tRNA常用内部启动子，U6等用外部启动子。","points":["内部启动子/下游启动子:","外部启动子/上游启动子:","2.1.3 RNA聚合酶III的启动子(III类启动子)","英文术语：RNA（核糖核酸）"],"level":"掌握","img":"assets/img/ch06/p048.jpg","src":"教师PPT","check":{"id":"ch06_ck_3_0","kind":"mcq","q":"III类启动子包括内部启动子和（ ）启动子","a":"A","e":"正确答案：外部。III类启动子有内部启动子和外部启动子。","src":"PPT对应自测","modI":3,"o":["A. 外部","B. 上游","C. 下游","D. 增强"]}},{"i":1,"page":49,"sec":"模块四：III类启动子","title":"Several kinds of class III promoters","notes":"本页主题：Several kinds of class III promoters\nPPT内容：Several kinds of class III promoters；Type I: 5S rRNA gene, has internal elements；Type II: tRNA et al., has internal elements；Type III: nonclassical promoters, has only external elements，U6 snRNA gene.；次近端序列元件（Proximal Sequence Element, PSE）；远端序列元件（Distal Sequence Element, DSE）\n讲解：III类启动子：5S rRNA为Type I内部启动子；tRNA为Type II内部启动子；U6等为Type III外部启动子。\n英文术语：启动子；snRNA（小核RNA）；rRNA（核糖体RNA）；tRNA（转运RNA）\n本页详解：“Several kinds of class III promoters”是III类启动子的类型。Type I：5S rRNA基因，含内部元件；Type II：tRNA等，含内部元件；Type III：非经典启动子，只有外部元件，如U6 snRNA。近端/远端序列元件PSE、DSE参与调控。","points":["Several kinds of class III promoters","Type I: 5S rRNA gene, has internal elements","Type II: tRNA et al., has internal elements","Type III: nonclassical promoters, has only external elements，U6 snRNA gene.","次近端序列元件（Proximal Sequence Element, PSE）","远端序列元件（Distal Sequence Element, DSE）","英文术语：启动子；snRNA（小核RNA）；rRNA（核糖体RNA）；tRNA（转运RNA）"],"level":"掌握","img":"assets/img/ch06/p049.jpg","src":"教师PPT","check":{"id":"ch06_ck_3_1","kind":"mcq","q":"5S rRNA和tRNA主要使用（ ）启动子","a":"B","e":"正确答案：内部。5S rRNA和tRNA基因通常使用内部启动子，U6则常用外部启动子。","src":"PPT对应自测","modI":3,"o":["A. 外部","B. 内部","C. 上游","D. 下游"]}},{"i":2,"page":50,"sec":"模块四：III类启动子","title":"启动子的活性依赖于一系列的转录因子和RNA聚合酶的装配。","notes":"本页主题：启动子的活性依赖于一系列的转录因子和RNA聚合酶的装配。\nPPT内容：启动子的活性依赖于一系列的转录因子和RNA聚合酶的装配。；Promoter activity depends on assembling a collection of transcription factors and RNA polymerase.；A preinitiation complex 前启始复合体；Gene promoter（DNA序列）；RNA polymerase （蛋白质复合体）；Transcription factors (TF, 转录因子，蛋白质或蛋白质复合体)；在核心启动子元件的基础上，多种调控元件共同作用。\n英文术语：前启始复合体；RNA聚合酶；转录；聚合酶；启动子；复合物；RNA（核糖核酸）；DNA（脱氧核糖核酸）\n本页详解：本页讲前启始复合体（preinitiation complex, PIC）。英文“Promoter activity depends on assembling a collection of transcription factors and RNA polymerase”意思是启动子活性依赖转录因子和RNA聚合酶装配成复合体。PIC包括启动子DNA、RNA聚合酶和转录因子；核心启动子基础上还需多种调控元件共同作用。","points":["启动子的活性依赖于一系列的转录因子和RNA聚合酶的装配。","Promoter activity depends on assembling a collection of transcription factors and RNA polymerase.","A preinitiation complex 前启始复合体","Gene promoter（DNA序列）","RNA polymerase （蛋白质复合体）","Transcription factors (TF, 转录因子，蛋白质或蛋白质复合体)","英文术语：前启始复合体；RNA聚合酶；转录；聚合酶；启动子；复合物；RNA（核糖核酸）；DNA（脱氧核糖核酸）"],"level":"掌握","img":"assets/img/ch06/p050.jpg","src":"教师PPT","check":{"id":"ch06_ck_3_2","kind":"fill","q":"启动子活性依赖转录因子和RNA聚合酶装配成______复合体。","a":"前启始","e":"答案：前启始。启动子活性依赖前启始复合体的装配。","src":"PPT对应自测","modI":3}}]},{"i":4,"name":"模块五：前启始复合体与启动子分析工具","slides":[{"i":0,"page":51,"sec":"模块五：前启始复合体与启动子分析工具","title":"Thank you !","notes":"本页主题：Thank you !\nPPT内容：Thank you !\n讲解：本模块讲前启始复合体与启动子分析工具：转录因子和RNA聚合酶装配，以及在线预测工具。\n本页详解：本页是模块结束页。复习时把RNA聚合酶类型、启动子类型、增强子/沉默子/绝缘子三条线串起来。","points":["Thank you !"],"level":"理解","img":"assets/img/ch06/p051.jpg","src":"教师PPT","check":null},{"i":1,"page":52,"sec":"模块五：前启始复合体与启动子分析工具","title":"核心启动子及转录起始位点预测使用在线工具NNPP( http://www.fruitfly.org/seq_tool","notes":"本页主题：核心启动子及转录起始位点预测使用在线工具NNPP( http://www.fruitfly.org/seq_tool\nPPT内容：核心启动子及转录起始位点预测使用在线工具NNPP( http://www.fruitfly.org/seq_tools/promoter.html；Berkeley Drosophila Genome Project；调控元件结合位点分析站；http://www.gene-regulation.com；http://www-bimas.cit.nih.gov/molbio/signal/；http://www.cbil.upenn.edu/cgi-bin/tess/tess；http://www.cbrc.jp/research/db/TFSEARCH.ht\n英文术语：启动子\n本页详解：本页给启动子预测工具。英文NNPP是核心启动子/转录起始位点预测工具；其他网站可分析调控元件结合位点。工具只给预测，实验还需验证。","points":["核心启动子及转录起始位点预测使用在线工具NNPP( http://www.fruitfly.org/seq_tools/promoter.html","Berkeley Drosophila Genome Project","调控元件结合位点分析站","http://www.gene-regulation.com","http://www-bimas.cit.nih.gov/molbio/signal/","http://www.cbil.upenn.edu/cgi-bin/tess/tess","英文术语：启动子"],"level":"理解","img":"assets/img/ch06/p052.jpg","src":"教师PPT","check":{"id":"ch06_ck_4_1","kind":"mcq","q":"预测核心启动子及转录起始位点可使用（ ）","a":"A","e":"正确答案：NNPP。NNPP是启动子/转录起始位点预测工具。","src":"PPT对应自测","modI":4,"o":["A. NNPP","B. BLAST","C. ClustalW","D. PyMOL"]}},{"i":2,"page":53,"sec":"模块五：前启始复合体与启动子分析工具","title":"http://molbiol-tools.ca/Promoters.htm 该网站详细记载了从2000年至今的通用分","notes":"本页主题：http://molbiol-tools.ca/Promoters.htm 该网站详细记载了从2000年至今的通用分\nPPT内容：http://molbiol-tools.ca/Promoters.htm 该网站详细记载了从2000年至今的通用分析程序；蛋白结构预测：Swiss Model（https://swissmodel.expasy.org/）\n英文术语：启动子\n本页详解：本页是启动子分析工具网站索引，例如PlantCARE、PlantProm、FPROM、BPROM等，另有Swiss Model做蛋白结构预测。学习时知道“用什么工具、预测什么”即可，不必背全部网址。","points":["http://molbiol-tools.ca/Promoters.htm 该网站详细记载了从2000年至今的通用分析程序","蛋白结构预测：Swiss Model（https://swissmodel.expasy.org/）","英文术语：启动子"],"level":"理解","img":"assets/img/ch06/p053.jpg","src":"教师PPT","check":{"id":"ch06_ck_4_2","kind":"fill","q":"molbiol-tools.ca 网站收录通用启动子分析______。","a":"工具","e":"答案：工具。该网站汇总启动子分析工具和数据库。","src":"PPT对应自测","modI":4}},{"i":3,"page":54,"sec":"模块五：前启始复合体与启动子分析工具","title":"模块五：前启始复合体与启动子分析工具 · 第54页","notes":"本页主题：模块五：前启始复合体与启动子分析工具 · 第54页\nPPT内容：本页为图示/过渡页。\n讲解：本模块讲前启始复合体与启动子分析工具：转录因子和RNA聚合酶装配，以及在线预测工具。\n本页详解：本页是模块五过渡页，主题是前启始复合体与启动子分析工具。把PIC装配和工具应用连起来。","points":["模块五：前启始复合体与启动子分析工具的图示关系","结合图片复述本页核心概念"],"level":"理解","img":"assets/img/ch06/p054.jpg","src":"教师PPT","check":{"id":"ch06_ck_4_3","kind":"mcq","q":"图中真核RNA聚合酶I主要转录（ ）","a":"C","e":"正确答案：rRNA前体。RNA聚合酶I位于核仁，主要转录rRNA前体。","src":"PPT对应自测","modI":4,"o":["A. tRNA","B. 5S rRNA","C. rRNA前体","D. mRNA前体"]}}]}],"mcq":[{"q":"真核生物转录的主要场所是（　）。","o":["A. 拟核","B. 细胞核","C. 核糖体","D. 线粒体基质"],"a":"B","e":"真核生物转录主要发生在细胞核，原核生物转录发生在拟核；真核生物还有线粒体和叶绿体中的少量转录。","kp":"ch06_s0_3","modI":0,"id":"ch06_mcq_1"},{"q":"真核生物mRNA通常为（　）。","o":["A. 多顺反子","B. 单顺反子","C. 双顺反子","D. 无编码区"],"a":"B","e":"真核生物mRNA通常为单顺反子，一个mRNA编码一条多肽链；原核生物常为多顺反子。","kp":"ch06_s0_3","modI":0,"id":"ch06_mcq_2"},{"q":"真核生物RNA聚合酶的特点是（　）。","o":["A. 只有一种，负责所有RNA合成","B. 有多种，分别转录不同类型的RNA","C. 不需要转录因子","D. 只存在于线粒体"],"a":"B","e":"真核生物有RNA聚合酶I、II、III等，分别负责rRNA、mRNA、tRNA/5S rRNA等合成；原核生物通常只有一种RNA聚合酶。","kp":"ch06_s0_3","modI":0,"id":"ch06_mcq_3"},{"q":"对α-鹅膏蕈碱最不敏感的RNA聚合酶是（　）。","o":["A. RNA聚合酶I","B. RNA聚合酶II","C. RNA聚合酶III","D. RNA聚合酶IV"],"a":"A","e":"RNA聚合酶I对α-鹅膏蕈碱不敏感，RNA聚合酶II最敏感，RNA聚合酶III敏感性居中。","kp":"ch06_s0_5","modI":0,"id":"ch06_mcq_4"},{"q":"对α-鹅膏蕈碱最敏感的RNA聚合酶是（　）。","o":["A. RNA聚合酶I","B. RNA聚合酶II","C. RNA聚合酶III","D. RNA聚合酶V"],"a":"B","e":"RNA聚合酶II对α-鹅膏蕈碱最敏感，低浓度即可被抑制；这是区分三类聚合酶的重要依据。","kp":"ch06_s0_5","modI":0,"id":"ch06_mcq_5"},{"q":"RNA聚合酶I的主要产物是（　）。","o":["A. mRNA","B. rRNA前体","C. tRNA","D. snRNA"],"a":"B","e":"RNA聚合酶I位于核仁，转录rDNA产生45S/47S rRNA前体，加工为18S、5.8S和28S rRNA。","kp":"ch06_s0_6","modI":0,"id":"ch06_mcq_6"},{"q":"RNA聚合酶II的主要产物是（　）。","o":["A. rRNA","B. hnRNA/mRNA前体","C. tRNA","D. 5S rRNA"],"a":"B","e":"RNA聚合酶II位于核质，转录产生hnRNA，多数加工为mRNA，也转录部分snRNA等。","kp":"ch06_s0_9","modI":0,"id":"ch06_mcq_7"},{"q":"RNA聚合酶III的主要产物是（　）。","o":["A. mRNA","B. tRNA、5S rRNA、部分snRNA","C. 28S rRNA","D. 线粒体mRNA"],"a":"B","e":"RNA聚合酶III转录tRNA、5S rRNA、U6 snRNA、7SL RNA等小RNA。","kp":"ch06_s0_11","modI":0,"id":"ch06_mcq_8"},{"q":"植物中特有的、产生小RNA并参与转座子沉默的RNA聚合酶是（　）。","o":["A. RNA聚合酶I","B. RNA聚合酶II","C. RNA聚合酶IV","D. RNA聚合酶III"],"a":"C","e":"植物有RNA聚合酶IV和V；Pol IV产生siRNA，参与转座子和重复DNA沉默；Pol V参与RNA介导的DNA甲基化等。","kp":"ch06_s0_13","modI":0,"id":"ch06_mcq_9"},{"q":"真核RNA聚合酶II通常由多少个亚基组成（　）。","o":["A. 3个","B. 5个","C. 12个左右","D. 50个"],"a":"C","e":"酵母和人类RNA聚合酶II约12个亚基；真核RNA聚合酶一般由8–16个亚基组成。","kp":"ch06_s0_17","modI":0,"id":"ch06_mcq_10"},{"q":"真核RNA聚合酶的两个大亚基与细菌RNA聚合酶的哪些亚基同源（　）。","o":["A. α和ω","B. β和β′","C. σ和α","D. β和σ"],"a":"B","e":"真核RNA聚合酶最大亚基RPB1与细菌β′同源，第二亚基RPB2与细菌β同源，构成催化中心。","kp":"ch06_s0_16","modI":0,"id":"ch06_mcq_11"},{"q":"三类真核RNA聚合酶共有的小亚基通常包括（　）。","o":["A. RPB1、RPB2","B. RPB5、RPB6、RPB8、RPB10、RPB12","C. σ70、σ32","D. CAP、AraC"],"a":"B","e":"三类聚合酶共享部分小亚基，如RPB5、6、8、10、12，功能尚不完全清楚。","kp":"ch06_s0_16","modI":0,"id":"ch06_mcq_12"},{"q":"RNA聚合酶II最大亚基的C端结构域（CTD）典型重复序列是（　）。","o":["A. Tyr-Ser-Pro-Thr-Ser-Pro-Ser","B. Gly-Ala-Gly-Ala","C. Lys-Arg-Lys-Arg","D. Asp-Glu-Asp-Glu"],"a":"A","e":"RNA聚合酶II的RPB1 CTD含7个氨基酸重复：Tyr-Ser-Pro-Thr-Ser-Pro-Ser；重复次数和磷酸化状态参与转录调控。","kp":"ch06_s0_22","modI":0,"id":"ch06_mcq_13"},{"q":"RNA聚合酶II CTD的磷酸化主要参与（　）。","o":["A. DNA复制起始","B. 转录起始、延伸及RNA加工偶联","C. 翻译终止","D. 蛋白质降解"],"a":"B","e":"CTD磷酸化状态招募加帽、剪接、加尾等因子，把转录与RNA加工偶联；CTD缺失大量重复序列可致死。","kp":"ch06_s0_22","modI":0,"id":"ch06_mcq_14"},{"q":"免疫共沉淀（co-IP）主要用于研究（　）。","o":["A. DNA序列","B. 蛋白质-蛋白质相互作用","C. RNA二级结构","D. 脂质组成"],"a":"B","e":"co-IP在非变性条件下用抗体沉淀目标蛋白，与其结合的蛋白也被共沉淀，用于鉴定蛋白复合物和相互作用。","kp":"ch06_s0_24","modI":0,"id":"ch06_mcq_15"},{"q":"表位标签（epitope tagging）技术的主要用途是（　）。","o":["A. 标记并分离目标蛋白及其复合物","B. 直接测定DNA序列","C. 编辑基因组","D. 检测RNA表达"],"a":"A","e":"将表位标签融合到目标蛋白，可用标签抗体进行检测、免疫沉淀和纯化，解析蛋白复合物组成。","kp":"ch06_s0_26","modI":0,"id":"ch06_mcq_16"},{"q":"I类启动子由哪些区域组成（　）。","o":["A. 核心启动子和上游控制元件UCE","B. TATA框和增强子","C. 操纵基因和CAP位点","D. 5′UTR和3′UTR"],"a":"A","e":"I类启动子由核心启动子（约-45至+20）和上游控制元件UCE（约-170至-107）组成；两者间距重要。","kp":"ch06_s1_3","modI":0,"id":"ch06_mcq_17"},{"q":"I类启动子的核心启动子通常位于（　）。","o":["A. -45至+20","B. -170至-107","C. -25至-10","D. +100至+200"],"a":"A","e":"I类启动子核心区约-45至+20，负责转录起始；UCE约-170至-107，提高起始效率。","kp":"ch06_s1_3","modI":0,"id":"ch06_mcq_18"},{"q":"I类启动子的特点是（　）。","o":["A. 序列在各物种间高度保守","B. 序列保守性较低，不同物种不完全一致","C. 只由TATA框组成","D. 由RNA聚合酶II识别"],"a":"B","e":"I类启动子由RNA聚合酶I识别，不同物种间序列保守性较低；核心区和UCE的间距重要。","kp":"ch06_s1_4","modI":0,"id":"ch06_mcq_19"},{"q":"三类真核启动子中最复杂的是（　）。","o":["A. I类启动子","B. II类启动子","C. III类启动子","D. 线粒体启动子"],"a":"B","e":"II类启动子由RNA聚合酶II识别，核心启动子可含TATA、BRE、Inr、DPE等多种元件，并受近端元件、增强子等调控，最复杂。","kp":"ch06_s2_1","modI":0,"id":"ch06_mcq_20"},{"q":"II类启动子的TATA框通常位于转录起始位点上游约（　）。","o":["A. -10 bp","B. -25 bp","C. -100 bp","D. -1000 bp"],"a":"B","e":"TATA框（Hogness框）通常中心位于-25 bp左右，一致序列富含T和A；它参与确定转录起始位点。","kp":"ch06_s2_3","modI":0,"id":"ch06_mcq_21"},{"q":"II类核心启动子的起始子（Inr）通常位于（　）。","o":["A. 转录起始位点附近","B. -100 bp","C. 内含子中","D. 终止子下游"],"a":"A","e":"Inr位于转录起始位点附近，共有序列约为PyPyAN(T/A)PyPy，参与启动子强度和起始位点选择。","kp":"ch06_s2_2","modI":0,"id":"ch06_mcq_22"},{"q":"TATA框丢失后，转录通常（　）。","o":["A. 完全停止","B. 在多个位点起始，起始位点选择变乱","C. 只从+1起始","D. 转为翻译"],"a":"B","e":"TATA框参与RNA聚合酶定位和起始位点选择；失去TATA框后转录可在多个位点开始。","kp":"ch06_s2_3","modI":0,"id":"ch06_mcq_23"},{"q":"GC框的核心序列是（　）。","o":["A. GGGCGG","B. CCAAT","C. TATAAT","D. TTGACA"],"a":"A","e":"GC框核心序列为GGGCGG，常结合Sp1等转录因子；无方向性，反转180°仍起作用。","kp":"ch06_s2_6","modI":0,"id":"ch06_mcq_24"},{"q":"CAAT框的典型核心序列是（　）。","o":["A. GGGCGG","B. CCAAT","C. TATAAT","D. TTAGGG"],"a":"B","e":"CAAT框核心序列为CCAAT，经典共识序列GG(C/T)CAATCT，常结合特异转录因子调节起始效率。","kp":"ch06_s2_7","modI":0,"id":"ch06_mcq_25"},{"q":"增强子的特点是（　）。","o":["A. 有方向性，只能位于上游","B. 无方向性，可位于上游或下游","C. 只抑制转录","D. 只存在于原核生物"],"a":"B","e":"增强子是顺式作用元件，无方向性，位置不依赖，可位于启动子上游或下游，结合转录因子增强转录。","kp":"ch06_s2_9","modI":0,"id":"ch06_mcq_26"},{"q":"沉默子的功能是（　）。","o":["A. 增强转录","B. 抑制相关基因转录","C. 终止翻译","D. 启动DNA复制"],"a":"B","e":"沉默子是与位置和方向无关的DNA元件，结合抑制性蛋白后抑制基因转录；有些元件可因结合蛋白不同而表现为增强子或沉默子。","kp":"ch06_s2_13","modI":0,"id":"ch06_mcq_27"},{"q":"绝缘子的主要功能是（　）。","o":["A. 阻止增强子或沉默子对邻近基因的影响","B. 直接编码蛋白质","C. 促进DNA复制","D. 催化RNA剪接"],"a":"A","e":"绝缘子可阻断增强子/沉默子对基因的作用，具有增强子阻断活性，维持染色质结构域的独立性。","kp":"ch06_s2_14","modI":0,"id":"ch06_mcq_28"},{"q":"超级增强子（super-enhancer）是指（　）。","o":["A. 单个增强子","B. 多个增强子密集组成的一簇调控元件","C. 一种沉默子","D. 一种启动子"],"a":"B","e":"超级增强子由多个增强子组成（间隔较小），调控能力更强，在细胞身份和发育调控中作用重要。","kp":"ch06_s2_12","modI":0,"id":"ch06_mcq_29"},{"q":"III类启动子中，5S rRNA基因的启动子通常属于（　）。","o":["A. 内部启动子","B. 外部启动子","C. TATA框","D. 增强子"],"a":"A","e":"III类启动子中，5S rRNA基因属Type I，具有内部启动子元件；tRNA基因也多为内部启动子。","kp":"ch06_s3_1","modI":0,"id":"ch06_mcq_30"},{"q":"III类启动子中，tRNA基因的启动子通常位于（　）。","o":["A. 基因内部","B. 基因上游很远","C. 终止子下游","D. 内含子中"],"a":"A","e":"tRNA基因属Type II，启动子位于转录起始位点下游的基因内部（A框、B框等）。","kp":"ch06_s3_1","modI":0,"id":"ch06_mcq_31"},{"q":"III类启动子中，只有外部启动子的类型是（　）。","o":["A. Type I","B. Type II","C. Type III","D. Type IV"],"a":"C","e":"III类启动子Type III为非经典启动子，只有外部启动子元件，如U6 snRNA基因。","kp":"ch06_s3_1","modI":0,"id":"ch06_mcq_32"},{"q":"前启始复合体（preinitiation complex）是指（　）。","o":["A. 转录因子和RNA聚合酶在启动子上装配的复合体","B. 核糖体与mRNA的复合体","C. DNA复制体","D. 剪接体"],"a":"A","e":"前启始复合体由通用转录因子、RNA聚合酶等在启动子上装配形成，负责转录起始。","kp":"ch06_s3_2","modI":0,"id":"ch06_mcq_33"},{"q":"α-鹅膏蕈碱抑制RNA聚合酶II的机制是（　）。","o":["A. 与RNA聚合酶II结合，阻断延伸","B. 降解DNA","C. 抑制核糖体","D. 抑制剪接"],"a":"A","e":"α-鹅膏蕈碱与RNA聚合酶II结合，阻断RNA链延伸；Pol I不敏感，Pol III敏感性较低。","kp":"ch06_s0_5","modI":0,"id":"ch06_mcq_34"},{"q":"真核启动子的定义是（　）。","o":["A. 转录起始所必需的序列元件，包括转录因子结合位点","B. 只指TATA框","C. 只指增强子","D. 核糖体结合位点"],"a":"A","e":"真核启动子是转录起始所需的序列元件区域，包含核心启动子及上游调控元件和转录因子结合位点。","kp":"ch06_s1_1","modI":0,"id":"ch06_mcq_35"},{"q":"增强子发挥作用的特点是（　）。","o":["A. 必须与启动子直接相邻","B. 位置和方向不依赖，可远距离作用","C. 只在原核生物中","D. 只抑制转录"],"a":"B","e":"增强子通过DNA环化等方式与启动子/转录因子接触，位置和方向不依赖，可远距离增强转录。","kp":"ch06_s2_9","modI":0,"id":"ch06_mcq_36"}],"judge":[{"id":"ch06_judge_1","q":"RNA聚合酶I对α-鹅膏蕈碱不敏感。","a":"对","e":"Pol I不敏感，Pol II最敏感，Pol III敏感性居中。","kp":"ch06_s0_5","modI":0},{"id":"ch06_judge_2","q":"RNA聚合酶II主要负责转录rRNA前体。","a":"错","e":"Pol I转录rRNA前体；Pol II转录hnRNA/mRNA前体等。","kp":"ch06_s0_9","modI":0},{"id":"ch06_judge_3","q":"真核生物RNA聚合酶II需要通用转录因子协助才能起始转录。","a":"对","e":"真核RNA聚合酶不能独立起始转录，需要转录因子装配前启始复合体。","kp":"ch06_s1_1","modI":0},{"id":"ch06_judge_4","q":"TATA框通常位于转录起始位点上游约-25 bp。","a":"对","e":"TATA框中心约-25 bp，参与起始位点选择。","kp":"ch06_s2_3","modI":0},{"id":"ch06_judge_5","q":"增强子具有方向性，反向插入后失去作用。","a":"错","e":"增强子无方向性，反向插入仍可增强转录。","kp":"ch06_s2_9","modI":0},{"id":"ch06_judge_6","q":"沉默子只能抑制转录，不能表现为增强子。","a":"错","e":"有些DNA元件可因结合蛋白不同而表现为增强子或沉默子。","kp":"ch06_s2_13","modI":0},{"id":"ch06_judge_7","q":"绝缘子可阻断增强子对邻近基因的作用。","a":"对","e":"绝缘子具有增强子阻断活性，维持染色质结构域独立。","kp":"ch06_s2_14","modI":0},{"id":"ch06_judge_8","q":"III类启动子中的tRNA基因使用内部启动子。","a":"对","e":"tRNA基因属Type II，启动子位于基因内部（A框、B框）。","kp":"ch06_s3_1","modI":0},{"id":"ch06_judge_9","q":"RNA聚合酶II最大亚基的CTD含7氨基酸重复序列。","a":"对","e":"CTD重复序列为Tyr-Ser-Pro-Thr-Ser-Pro-Ser，参与转录和RNA加工偶联。","kp":"ch06_s0_22","modI":0},{"id":"ch06_judge_10","q":"真核生物只有RNA聚合酶I、II、III三种。","a":"错","e":"植物还有Pol IV和Pol V；线粒体/叶绿体还有各自的RNA聚合酶。","kp":"ch06_s0_13","modI":0}],"fill":[{"id":"ch06_fill_1","q":"真核生物RNA聚合酶I的主要产物是________前体。","a":"rRNA","e":"Pol I在核仁转录rDNA，产生45S/47S rRNA前体。","kp":"ch06_s0_6","modI":0},{"id":"ch06_fill_2","q":"对α-鹅膏蕈碱最敏感的RNA聚合酶是________。","a":"RNA聚合酶II","e":"Pol II对α-鹅膏蕈碱最敏感，低浓度即被抑制。","kp":"ch06_s0_5","modI":0},{"id":"ch06_fill_3","q":"RNA聚合酶II最大亚基的C端结构域简称________。","a":"CTD","e":"CTD为C-terminal domain，含7氨基酸重复，参与转录调控和RNA加工偶联。","kp":"ch06_s0_22","modI":0},{"id":"ch06_fill_4","q":"I类启动子由核心启动子和________组成。","a":"上游控制元件","e":"I类启动子含核心启动子（-45至+20）和UCE（约-170至-107）。","kp":"ch06_s1_3","modI":0},{"id":"ch06_fill_5","q":"II类启动子的TATA框通常位于________ bp附近。","a":"-25","e":"TATA框中心约-25 bp，参与起始位点选择。","kp":"ch06_s2_3","modI":0},{"id":"ch06_fill_6","q":"GC框的核心序列是________。","a":"GGGCGG","e":"GC框常结合Sp1，无方向性。","kp":"ch06_s2_6","modI":0},{"id":"ch06_fill_7","q":"CAAT框的典型核心序列是________。","a":"CCAAT","e":"CAAT框通过特异转录因子调节起始效率。","kp":"ch06_s2_8","modI":0},{"id":"ch06_fill_8","q":"增强子的两个特点是位置不依赖和________不依赖。","a":"方向","e":"增强子可位于上游或下游，反向插入仍有效。","kp":"ch06_s2_9","modI":0},{"id":"ch06_fill_9","q":"III类启动子中，tRNA基因属于________启动子。","a":"内部","e":"tRNA基因属Type II，启动子位于基因内部。","kp":"ch06_s3_1","modI":0},{"id":"ch06_fill_10","q":"转录因子和RNA聚合酶在启动子上装配形成________复合体。","a":"前启始","e":"前启始复合体负责转录起始。","kp":"ch06_s4_1","modI":0}],"short":[{"id":"ch06_short_1","q":"比较真核生物RNA聚合酶I、II、III的主要产物、位置和对α-鹅膏蕈碱的敏感性。","a":"Pol I：位于核仁，转录rRNA前体（45S/47S，加工为18S、5.8S、28S），对α-鹅膏蕈碱不敏感。Pol II：位于核质，转录hnRNA/mRNA前体及部分snRNA，对α-鹅膏蕈碱最敏感。Pol III：位于核质，转录tRNA、5S rRNA、U6 snRNA、7SL RNA等，敏感性居中。植物还有Pol IV/V。","kps":"Pol I核仁/rRNA/不敏感；Pol II核质/mRNA/最敏感；Pol III核质/tRNA/5S/居中；Pol IV/V植物。","kp":"ch06_s0_5","modI":0},{"id":"ch06_short_2","q":"简述II类启动子的核心元件及其功能。","a":"II类核心启动子可含TATA框、BRE、Inr、DPE等。TATA框约-25 bp，参与RNA聚合酶定位和起始位点选择；Inr位于起始位点附近，影响启动子强度和起始位点；BRE是TFIIB识别元件；DPE位于下游，参与TFIID结合。核心启动子单独存在即可起始基础转录，近端元件和增强子提高效率与特异性。","kps":"TATA -25；Inr起始位点；BRE TFIIB；DPE TFIID；核心启动子基础转录。","kp":"ch06_s2_3","modI":0},{"id":"ch06_short_3","q":"比较增强子、沉默子和绝缘子的功能特点。","a":"增强子：顺式DNA元件，无方向性、位置不依赖，可远距离增强转录。沉默子：无方向性、位置不依赖，结合抑制蛋白抑制转录；有些元件可因结合蛋白不同而表现为增强子或沉默子。绝缘子：阻断增强子/沉默子对邻近基因的作用，具有增强子阻断活性，维持染色质结构域独立。","kps":"增强子增强；沉默子抑制；绝缘子阻断；均顺式、方向/位置特征。","kp":"ch06_s2_14","modI":0},{"id":"ch06_short_4","q":"简述真核RNA聚合酶II的亚基组成和CTD的功能。","a":"RNA聚合酶II约12个亚基，最大亚基RPB1和第二亚基RPB2与细菌β′/β同源，构成催化中心；还含共享小亚基RPB5/6/8/10/12等。RPB1 C端有CTD，含7氨基酸重复（Tyr-Ser-Pro-Thr-Ser-Pro-Ser），其磷酸化状态招募加帽、剪接、加尾因子，把转录与RNA加工偶联；CTD重复序列大量缺失可致死。","kps":"12亚基；RPB1/2催化；共享小亚基；CTD七肽重复；磷酸化招募加工因子；转录-加工偶联。","kp":"ch06_s0_22","modI":0},{"id":"ch06_short_5","q":"简述III类启动子的类型及特点。","a":"III类启动子由RNA聚合酶III识别，主要有：Type I（5S rRNA基因），具有内部启动子元件；Type II（tRNA基因等），具有内部启动子（A框、B框）；Type III（如U6 snRNA基因），只有外部启动子，属非经典启动子。III类启动子也需要转录因子协助RNA聚合酶III装配。","kps":"Type I 5S内部；Type II tRNA内部；Type III U6外部；需转录因子。","kp":"ch06_s3_1","modI":0}],"calc":[{"id":"ch06_calc_1","q":"论述真核生物II类启动子的结构层次，并说明核心启动子、近端元件和增强子如何协同调控转录。","a":"II类启动子由核心启动子、近端调控元件和远端增强子等组成。核心启动子位于起始位点附近，含TATA框、Inr、BRE、DPE等，负责基础转录和起始位点选择；TATA框约-25 bp，Inr位于+1附近。近端元件如GC框、CAAT框位于核心启动子上游，结合Sp1等转录因子，提高转录效率和细胞类型特异性。增强子无方向性、位置不依赖，可位于上游或下游，通过DNA环化与启动子/转录因子接触，进一步增强转录；多个增强子可形成超级增强子。三类元件协同，实现基础转录、组织特异性和发育时序的精细调控。","steps":"核心启动子TATA/Inr/BRE/DPE；近端GC/CAAT；增强子无方向/远距离；超级增强子；协同调控。","kp":"ch06_s2_9","modI":0},{"id":"ch06_calc_2","q":"论述真核RNA聚合酶的分类、结构共性与功能分化，并说明研究其亚基组成的方法。","a":"分类：Pol I转录rRNA前体，Pol II转录mRNA前体，Pol III转录tRNA/5S rRNA等；植物还有Pol IV/V。结构共性：均为多亚基蛋白（8–16个），含两个大亚基RPB1/RPB2，与细菌β′/β同源，构成催化中心；三类酶共享部分小亚基；Pol II RPB1有CTD七肽重复。功能分化：不同聚合酶识别不同启动子、转录不同RNA，并受不同转录因子调控；Pol II CTD把转录与RNA加工偶联。研究方法：非变性裂解后进行免疫共沉淀（co-IP），用抗体沉淀目标亚基并鉴定共沉淀蛋白；表位标签融合目标亚基，用标签抗体纯化复合物；结合质谱鉴定亚基组成。","steps":"Pol I/II/III产物；RPB1/2同源；共享小亚基；CTD；co-IP；表位标签；质谱。","kp":"ch06_s0_24","modI":0}],"term":[{"id":"ch06_term_1","term":"RNA polymerase I","def":"RNA聚合酶I：位于核仁，转录rDNA产生rRNA前体，加工为18S、5.8S、28S rRNA；对α-鹅膏蕈碱不敏感。","kps":"","kp":"ch06_s0_6","modI":0},{"id":"ch06_term_2","term":"RNA polymerase II","def":"RNA聚合酶II：位于核质，转录hnRNA/mRNA前体及部分snRNA；对α-鹅膏蕈碱最敏感；最大亚基含CTD。","kps":"","kp":"ch06_s0_9","modI":0},{"id":"ch06_term_3","term":"RNA polymerase III","def":"RNA聚合酶III：位于核质，转录tRNA、5S rRNA、U6 snRNA、7SL RNA等；对α-鹅膏蕈碱敏感性居中。","kps":"","kp":"ch06_s0_11","modI":0},{"id":"ch06_term_4","term":"CTD","def":"RNA聚合酶II最大亚基C端结构域：含Tyr-Ser-Pro-Thr-Ser-Pro-Ser七肽重复，磷酸化后招募RNA加工因子，偶联转录与加工。","kps":"","kp":"ch06_s0_22","modI":0},{"id":"ch06_term_5","term":"Core promoter","def":"核心启动子：位于转录起始位点附近（约-45至+20），含TATA、Inr、BRE、DPE等，单独存在即可起始基础转录。","kps":"","kp":"ch06_s1_3","modI":0},{"id":"ch06_term_6","term":"TATA box","def":"TATA框/Hogness框：位于约-25 bp，富含T/A，参与RNA聚合酶定位和转录起始位点选择。","kps":"","kp":"ch06_s2_3","modI":0},{"id":"ch06_term_7","term":"Initiator (Inr)","def":"起始子：位于转录起始位点附近，共有序列PyPyAN(T/A)PyPy，影响启动子强度和起始位点选择。","kps":"","kp":"ch06_s2_2","modI":0},{"id":"ch06_term_8","term":"GC box","def":"GC框：核心序列GGGCGG，常结合Sp1，无方向性，位于启动子上游，提高转录效率。","kps":"","kp":"ch06_s2_6","modI":0},{"id":"ch06_term_9","term":"Enhancer","def":"增强子：顺式DNA元件，无方向性、位置不依赖，可远距离增强基因转录。","kps":"","kp":"ch06_s2_9","modI":0},{"id":"ch06_term_10","term":"Silencer","def":"沉默子：无方向性、位置不依赖的DNA元件，结合抑制蛋白后抑制转录；有些元件可表现为增强子或沉默子。","kps":"","kp":"ch06_s2_13","modI":0},{"id":"ch06_term_11","term":"Insulator","def":"绝缘子：阻断增强子或沉默子对邻近基因作用的DNA元件，维持染色质结构域独立。","kps":"","kp":"ch06_s2_14","modI":0},{"id":"ch06_term_12","term":"Preinitiation complex","def":"前启始复合体：通用转录因子和RNA聚合酶在启动子上装配形成的复合体，负责转录起始。","kps":"","kp":"ch06_s4_1","modI":0}],"preview":{"main":"本部分聚焦真核转录装置和启动子：RNA聚合酶I/II/III、亚基与CTD、I/II/III类启动子、核心启动子、近端元件、增强子/沉默子/绝缘子。","questions":["真核三类RNA聚合酶如何分工？","II类核心启动子由哪些元件组成？","增强子、沉默子、绝缘子有何区别？","如何研究RNA聚合酶II的亚基组成？"]},"appcards":[]};
